ANSI16_RGB = [0x000000, 0xCD3131, 0x0DBC79, 0xE5E510, 0x2472C8, 0xBC3FBC, 0x11A8CD, 0xE5E5E5,
              0x666666, 0xF14C4C, 0x23D18B, 0xF5F543, 0x3B8EEA, 0xD670D6, 0x29B8DB, 0xFFFFFF]


def xterm256() -> list[int]:
    lv = [0, 95, 135, 175, 215, 255]
    out = list(ANSI16_RGB)
    for r in lv:
        for g in lv:
            for b in lv:
                out.append((r << 16) | (g << 8) | b)
    for i in range(24):
        v = 8 + 10 * i
        out.append((v << 16) | (v << 8) | v)
    return out


GRAY26 = [0x000000] + [((8 + 10 * i) * 0x010101) for i in range(24)] + [0xFFFFFF]
BAYER8 = [[0, 32, 8, 40, 2, 34, 10, 42], [48, 16, 56, 24, 50, 18, 58, 26], [12, 44, 4, 36, 14, 46, 6, 38],
          [60, 28, 52, 20, 62, 30, 54, 22], [3, 35, 11, 43, 1, 33, 9, 41], [51, 19, 59, 27, 49, 17, 57, 25],
          [15, 47, 7, 39, 13, 45, 5, 37], [63, 31, 55, 23, 61, 29, 53, 21]]
MATRIX_GLYPHS = "".join(chr(c) for c in range(0xFF66, 0xFF9E)) + "0123456789"


# ---------------------------------------------------------------------- planning
def plan_grid(src_w: int, src_h: int, p: dict) -> dict:
    """Output geometry: character columns/rows, sample grid and working resolution."""
    m = MODES[p["mode"]]
    sx, sy, unit = m[2], m[3], m[4]
    cols = max(8, int(p["cols"]))
    gcols = max(4, cols // unit)
    pix_aspect = p["cell_aspect"] * unit  # width/height of one logical cell
    src_aspect = src_w / max(1, src_h)
    target = p["target_aspect"] if p["target_aspect"] > 0 else src_aspect
    if p["rows"] > 0 and p["lock_aspect"]:
        rows_fit = p["rows"]
        rows = max(1, int(gcols * pix_aspect / target + 0.5))
        if rows > rows_fit:  # automatic fit inside cols × rows
            rows = rows_fit
            gcols = max(4, int(rows * target / pix_aspect + 0.5))
    elif p["rows"] > 0:
        rows = p["rows"]
    else:
        rows = max(1, int(gcols * pix_aspect / target + 0.5))
    rows = min(rows, 1000)
    sw, sh = gcols * sx, rows * sy
    return {"cols": gcols * unit, "gcols": gcols, "rows": rows, "sx": sx, "sy": sy, "unit": unit,
            "sw": sw, "sh": sh, "target_aspect": target}


# measured cost per sample in µs (Python, tools/benchmark_image.py); the JS edition is ~3-4× faster
MODE_COST_US = {"sextant": 3.3, "quadrant": 1.6, "dense": 1.6, "ansi16": 5.8, "line": 1.0, "mosaic": 0.7, "multilayer": 0.9,
                "silhouette": 0.6, "typographic": 0.45, "math": 0.45, "adaptive": 0.45, "extended": 0.9}


def estimate_cost(src_w: int, src_h: int, p: dict, js: bool = False) -> dict:
    """Memory/time estimate shown before expensive renders (calibrated on benchmarks, ±50 %)."""
    g = plan_grid(src_w, src_h, p)
    cells = g["gcols"] * g["rows"]
    samples = g["sw"] * g["sh"]
    per = MODE_COST_US.get(p["mode"], 0.6)
    if p["dither"] in ("floyd", "atkinson") or p["mode"] in ("blocks", "mono"):
        per += 0.5
    ms = 60 + samples * per / 1000
    if js:
        ms /= 3.5
    ansi_bytes = cells * (40 if p["color"] != "none" or MODES[p["mode"]][1] == "color" else 3)
    mem = samples * 8 * 12 + cells * 120
    return {"cols": g["cols"], "rows": g["rows"], "cells": cells, "samples": samples, "est_ms": round(ms, 1),
            "est_text_bytes": cells * 3 + g["rows"], "est_ansi_bytes": ansi_bytes, "est_memory_bytes": mem,
            "heavy": ms > 2500 or mem > 600 * 1024 * 1024}


def prepare(src: RasterImage, p: dict) -> tuple[RasterImage, dict]:
    """Geometry → working resolution → adjustments. Returns (work image, grid plan).

    The geometry/resampling stage is cached on the source image (it depends only on geometry settings
    and the output grid), so changing adjustments or modes does not re-resample a large source."""
    gkeys = ("crop_x0", "crop_y0", "crop_x1", "crop_y1", "rotate", "flip_h", "flip_v", "angle", "pad", "target_aspect",
             "fit", "cols", "rows", "cell_aspect", "lock_aspect", "mode")
    m = MODES[p["mode"]]
    key = (id(src), src.width, src.height) + tuple(p[k] for k in gkeys[:-1]) + (m[2], m[3], m[4])
    cache = src.info.setdefault("_geom_cache", {})
    hit = cache.get(key)
    if hit is None:
        hit = _prepare_geometry(src, p)
        if len(cache) >= 6:
            cache.pop(next(iter(cache)))
        cache[key] = hit
    img, g = hit
    adj = {k: p[k] for k in ADJUST_DEFAULTS}
    return adjust(img, adj), dict(g)


def _prepare_geometry(src: RasterImage, p: dict):
    img = src
    if (p["crop_x0"], p["crop_y0"], p["crop_x1"], p["crop_y1"]) != (0.0, 0.0, 1.0, 1.0):
        img = crop(img, p["crop_x0"], p["crop_y0"], p["crop_x1"], p["crop_y1"])
    if p["rotate"]:
        img = rotate90(img, p["rotate"])
    if p["flip_h"] or p["flip_v"]:
        img = flip(img, p["flip_h"], p["flip_v"])
    if p["angle"]:
        img = rotate_free(img, p["angle"])
    if p["pad"] > 0:
        k = int(max(img.width, img.height) * p["pad"] + 0.5)
        img = pad(img, k, k, k, k)
    g = plan_grid(img.width, img.height, p)
    if p["target_aspect"] > 0 and p["fit"] != "stretch":
        cur = img.width / img.height
        tgt = p["target_aspect"]
        if p["fit"] == "contain":
            if cur > tgt:
                extra = int(img.width / tgt - img.height + 0.5); img = pad(img, 0, extra // 2, 0, extra - extra // 2)
            else:
                extra = int(img.height * tgt - img.width + 0.5); img = pad(img, extra // 2, 0, extra - extra // 2, 0)
        else:
            if cur > tgt:
                nw = img.height * tgt / img.width; img = crop(img, (1 - nw) / 2, 0, (1 + nw) / 2, 1)
            else:
                nh = img.width / tgt / img.height; img = crop(img, 0, (1 - nh) / 2, 1, (1 + nh) / 2)
    ww = min(img.width, max(g["sw"] * 2, 16))
    wh = max(1, int(img.height * ww / img.width + 0.5))
    if (ww, wh) != (img.width, img.height):
        img = resample_area(img, ww, wh)
    img = RasterImage(img.rgb, img.a, {k: v for k, v in img.info.items() if k != "_geom_cache"})
    return img, g


# ---------------------------------------------------------------------- context
class Ctx:
    """Per-render helpers shared by the mode functions."""

    def __init__(self, work: RasterImage, g: dict, p: dict):
        self.work, self.g, self.p = work, g, p
        self.bg = parse_color_list(p["background"])[0] if parse_color_list(p["background"]) else 0
        self._cache = {}
        self.rng_seed = p["seed"]

    def flat(self):
        if "flat" not in self._cache:
            self._cache["flat"] = composite(self.work, self.bg)
        return self._cache["flat"]

    def grid(self, sx: int | None = None, sy: int | None = None):
        """(rgb, alpha) sampled to gcols*sx × rows*sy by area averaging."""
        sx = self.g["sx"] if sx is None else sx
        sy = self.g["sy"] if sy is None else sy
        key = ("grid", sx, sy)
        if key not in self._cache:
            w, h = self.g["gcols"] * sx, self.g["rows"] * sy
            r = resample_area(self.work, w, h)
            br, bg_, bb = int_to_rgb01(self.bg)
            flat = r.rgb * r.a[:, :, None] + np.array([br, bg_, bb]) * (1 - r.a[:, :, None])
            self._cache[key] = (flat, r.a)
        return self._cache[key]

    def lum(self, rgb):
        return luminance(rgb, self.p["luma"])

    def ink(self, rgb, a, light_on_dark=None):
        L = self.lum(rgb)
        lod = self.p["light_on_dark"] if light_on_dark is None else light_on_dark
        v = L if lod else 1.0 - L
        if self.p["transparent_bg"]:
            v = np.where(a < 0.5, 0.0, v)
        return np.clip(v, 0, 1)

    def blank(self, a):
        """Cells that should stay empty because the source is transparent there."""
        if not self.p["transparent_bg"]:
            return np.zeros(a.shape, dtype=bool)
        return a < 0.5


# ---------------------------------------------------------------------- colour engine
def _nearest_palette(rgb_cells, palette: list[int]):
    """Nearest palette colour in CIELAB (ΔE76), with an exact-colour cache."""
    flat = rgb_cells.reshape(-1, 3)
    keys = rgb01_to_int(flat)
    uniq, inv = np.unique(keys, return_inverse=True)
    pal = np.array([int_to_rgb01(c) for c in palette])
    plab = rgb_to_lab(pal)
    u_rgb = np.stack([(uniq >> 16) & 255, (uniq >> 8) & 255, uniq & 255], axis=1) / 255.0
    ulab = rgb_to_lab(u_rgb)
    out = np.zeros(len(uniq), dtype=np.int64)
    for s in range(0, len(uniq), 8192):
        d = ((ulab[s:s + 8192, None, :] - plab[None, :, :]) ** 2).sum(axis=2)
        out[s:s + 8192] = np.argmin(d, axis=1)
    return np.array(palette, dtype=np.int64)[out[inv.ravel()]].reshape(rgb_cells.shape[:-1])


def color_palette(ctx: Ctx, mode: str) -> list[int] | None:
    p = ctx.p
    if mode == "ansi16":
        return ANSI16_RGB
    if mode == "ansi256":
        return xterm256()
    if mode == "custom":
        return parse_color_list(p["colors"]) or [0, 0xFFFFFF]
    if mode == "dominant":
        if "dominant" not in ctx._cache:
            ctx._cache["dominant"] = [int(r * 255 + 0.5) << 16 | int(g * 255 + 0.5) << 8 | int(b * 255 + 0.5)
                                      for r, g, b in median_cut(ctx.flat(), p["dominant_k"])]
        return ctx._cache["dominant"]
    return None


def map_colors(ctx: Ctx, rgb, mode: str | None = None):
    """Colour engine: cell colours → 0xRRGGBB int array (or None for monochrome output)."""
    mode = ctx.p["color"] if mode is None else mode
    if mode == "none":
        return None
    if mode == "original":
        return rgb01_to_int(rgb)
    if mode == "grayscale":
        L = luminance(rgb)
        return rgb01_to_int(np.repeat(L[..., None], 3, axis=-1))
    if mode == "gradient":
        stops = parse_color_list(ctx.p["gradient"]) or [0, 0xFFFFFF]
        L = luminance(rgb)
        lut = [gradient_color(stops, i / 255) for i in range(256)]
        return np.array(lut, dtype=np.int64)[np.clip(np.floor(L * 255 + 0.5), 0, 255).astype(np.int64)]
    pal = color_palette(ctx, mode)
    return _nearest_palette(rgb, pal)


def _contrast_fg(colors):
    """Black or white text for coloured backgrounds."""
    r, g, b = (colors >> 16) & 255, (colors >> 8) & 255, colors & 255
    return np.where(0.2126 * r + 0.7152 * g + 0.0722 * b > 140, 0x111111, 0xF5F5F5)


def _dim(colors, f: float):
    r, g, b = (colors >> 16) & 255, (colors >> 8) & 255, colors & 255
    return (np.floor(r * f + 0.5).astype(np.int64) << 16) | (np.floor(g * f + 0.5).astype(np.int64) << 8) | np.floor(b * f + 0.5).astype(np.int64)


def build_art(chars, fg=None, bg=None, blank=None) -> Art:
    """numpy/list grids → Art (None where no colour)."""
    rows = [list(r) for r in chars] if not isinstance(chars, list) else chars
    h = len(rows)
    w = len(rows[0]) if h else 0

    def conv(c):
        if c is None:
            return [[None] * w for _ in range(h)]
        lst = c.tolist()
        if blank is not None:
            bl = blank.tolist()
            for y in range(h):
                for x in range(w):
                    if bl[y][x]:
                        lst[y][x] = None
        return lst
    if blank is not None:
        bl = blank.tolist()
        for y in range(h):
            r = rows[y]
            for x in range(w):
                if bl[y][x]:
                    r[x] = " "
    return Art(rows, conv(fg), conv(bg))


def apply_char_colors(ctx: Ctx, chars, rgb, blank=None) -> Art:
    """Assign colours for single-character-per-cell modes according to color/color_target."""
    cols = map_colors(ctx, rgb)
    if cols is None:
        return build_art(chars, blank=blank)
    t = ctx.p["color_target"]
    if t == "fg":
        return build_art(chars, cols, None, blank)
    if t == "bg":
        return build_art(chars, _contrast_fg(cols), cols, blank)
    return build_art(chars, cols, _dim(cols, 0.3), blank)


# ---------------------------------------------------------------------- quantisation / dithering
def density_levels(chars: list[str]) -> list[float]:
    s = [glyph_coverage_sum(c) for c in chars]
    lo, hi = min(s), max(s)
    if hi == lo:
        n = len(chars)
        return [i / max(1, n - 1) for i in range(n)]
    return [(v - lo) / (hi - lo) for v in s]


def _nearest_level(levels: list[float], v: float) -> int:
    i = bisect_left(levels, v)
    if i <= 0:
        return 0
    if i >= len(levels):
        return len(levels) - 1
    return i - 1 if v - levels[i - 1] <= levels[i] - v else i


def quantize_levels(values, levels: list[float], method: str = "none", strength: float = 1.0):
    """Map a 2-D array of 0..1 values to indices of (ascending) levels with optional dithering."""
    H, W = values.shape
    n = len(levels)
    if method in ("none", "bayer"):
        v = values
        if method == "bayer" and n > 1:
            step = 1.0 / (n - 1)
            B = np.array(BAYER8, dtype=np.float64)
            tile = B[np.arange(H)[:, None] % 8, np.arange(W)[None, :] % 8]
            v = values + (tile / 64.0 - 0.5 + 1 / 128) * step * strength
        L = np.array(levels)
        i = np.clip(np.searchsorted(L, v, side="left"), 0, n - 1)
        im1 = np.clip(i - 1, 0, n - 1)
        choose_lower = (i > 0) & ((v - L[im1]) <= (L[i] - v))
        return np.where(choose_lower, im1, i)
    g = values.tolist()
    out = [[0] * W for _ in range(H)]
    if method == "floyd":
        taps = ((1, 0, 7 / 16), (-1, 1, 3 / 16), (0, 1, 5 / 16), (1, 1, 1 / 16))
    else:  # atkinson
        taps = ((1, 0, 1 / 8), (2, 0, 1 / 8), (-1, 1, 1 / 8), (0, 1, 1 / 8), (1, 1, 1 / 8), (0, 2, 1 / 8))
    for y in range(H):
        row = g[y]
        orow = out[y]
        for x in range(W):
            v = row[x]
            q = _nearest_level(levels, v)
            orow[x] = q
            err = (v - levels[q]) * strength
            if err:
                for dx, dy, f in taps:
                    xx, yy = x + dx, y + dy
                    if 0 <= xx < W and yy < H:
                        g[yy][xx] += err * f
    return np.array(out, dtype=np.int64)


def adaptive_mask(ink, threshold: float, radius: int | None = None):
    """Local-mean adaptive threshold: on where ink exceeds the neighbourhood mean by an offset."""
    r = radius if radius is not None else max(2, min(ink.shape) // 12)
    mean = box_mean(ink, r)
    return ink > mean + (threshold - 0.5) * 0.4


def binarize(ctx: Ctx, ink):
    p = ctx.p
    if p["adaptive"]:
        return adaptive_mask(ink, p["threshold"]) & (ink > 0.04)
    if p["dither"] != "none":
        q = quantize_levels(ink, [0.0, 1.0], p["dither"], p["dither_strength"])
        return q == 1
    return ink >= p["threshold"]


# ---------------------------------------------------------------------- shared renderers
def _ramp(ctx: Ctx, chars: list[str], ink, rgb, a, dither: str | None = None):
    levels = density_levels(chars)
    q = quantize_levels(ink, levels, dither or ctx.p["dither"], ctx.p["dither_strength"])
    arr = np.array(chars, dtype=object)[q]
    return apply_char_colors(ctx, arr.tolist(), rgb, ctx.blank(a))


def _palette(ctx: Ctx, mode: str) -> list[str]:
    return resolve_palette(ctx.p["palette"] or DEFAULT_PALETTE.get(mode, "ascii_extended"), reverse=ctx.p["palette_reverse"])


def _cell_features(arr, fw: int, fh: int):
    """(rows*fh, cols*fw[,C]) → (rows*cols, fh*fw[,C]) blocks in reading order."""
    H, W = arr.shape[:2]
    rows, cols = H // fh, W // fw
    if arr.ndim == 2:
        return arr.reshape(rows, fh, cols, fw).transpose(0, 2, 1, 3).reshape(rows * cols, fh * fw)
    C = arr.shape[2]
    return arr.reshape(rows, fh, cols, fw, C).transpose(0, 2, 1, 3, 4).reshape(rows * cols, fh * fw, C)


def _cell_mean_rgb(rgb, fw, fh):
    return _cell_features(rgb, fw, fh).mean(axis=1).reshape(rgb.shape[0] // fh, rgb.shape[1] // fw, 3)


def _cell_mean(a, fw, fh):
    return _cell_features(a, fw, fh).mean(axis=1).reshape(a.shape[0] // fh, a.shape[1] // fw)


_MATCHERS: dict = {}


def matcher_for(chars: list[str], fw: int, fh: int, k: int = 24) -> GlyphMatcher:
    key = ("".join(chars), fw, fh, k)
    m = _MATCHERS.get(key)
    if m is None:
        if len(_MATCHERS) > 24:
            _MATCHERS.clear()
        m = _MATCHERS[key] = GlyphMatcher(chars, fw, fh, k)
    return m


def _shape_match(ctx: Ctx, chars: list[str], fw: int, fh: int, k: int = 24, ink=None):
    rgb, a = ctx.grid(fw, fh)
    if ink is None:
        ink = ctx.ink(rgb, a)
    m = matcher_for(chars, fw, fh, k)
    idx = m.match(_cell_features(ink, fw, fh))
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    out = np.array(m.chars, dtype=object)[idx].reshape(rows, cols)
    return out, _cell_mean_rgb(rgb, fw, fh), _cell_mean(a, fw, fh)


def _fit_masks(P, M, chunk: int = 2048):
    """Least-squares two-colour fit of every cell P (n,F,3) against every mask M (G,F).

    For mask m the optimal colours solve [Σm² Σm(1−m); Σm(1−m) Σ(1−m)²]·[fg; bg] = [Σm·P; Σ(1−m)·P];
    colours are clipped to 0–1 and the exact squared error of the clipped colours is used.
    Returns (best glyph index, fg (n,3), bg (n,3)). Ties keep the lower glyph index.
    """
    n, F = P.shape[0], P.shape[1]
    G = M.shape[0]
    s1 = M.sum(axis=1); s2 = (M * M).sum(axis=1)
    a11, a12, a22 = s2, s1 - s2, F - 2 * s1 + s2
    det = a11 * a22 - a12 * a12
    sing = np.abs(det) < 1e-9
    sdet = np.where(sing, 1.0, det)
    best_g = np.zeros(n, dtype=np.int64); best_fg = np.zeros((n, 3)); best_bg = np.zeros((n, 3))
    for s in range(0, n, chunk):
        Pc = P[s:s + chunk]
        sumP = Pc.sum(axis=1)                         # (c,3)
        sq = (Pc * Pc).sum(axis=(1, 2))                # (c,)
        mp = np.einsum("nfc,gf->ngc", Pc, M)          # (c,G,3)
        b2 = sumP[:, None, :] - mp
        fg = (a22[None, :, None] * mp - a12[None, :, None] * b2) / sdet[None, :, None]
        bg = (a11[None, :, None] * b2 - a12[None, :, None] * mp) / sdet[None, :, None]
        mean = (sumP / F)[:, None, :]
        fg = np.where(sing[None, :, None], mean, fg); bg = np.where(sing[None, :, None], mean, bg)
        fg = np.clip(fg, 0, 1); bg = np.clip(bg, 0, 1)
        err = (sq[:, None] - 2 * (fg * mp).sum(axis=2) - 2 * (bg * b2).sum(axis=2)
               + (fg * fg).sum(axis=2) * s2[None, :] + 2 * (fg * bg).sum(axis=2) * a12[None, :]
               + (bg * bg).sum(axis=2) * a22[None, :])
        err = np.floor(err * 1e8 + 0.5)  # quantised so mathematically tied glyphs resolve identically in both editions
        gi = np.argmin(err, axis=1)
        r = np.arange(len(Pc))
        best_g[s:s + chunk] = gi
        best_fg[s:s + chunk] = fg[r, gi]
        best_bg[s:s + chunk] = bg[r, gi]
    return best_g, best_fg, best_bg


def _two_color_patterns(ctx: Ctx, sx: int, sy: int, char_of):
    """Exhaustive two-colour partition per cell over all 2^(sx*sy) patterns (minimises squared RGB error)."""
    rgb, a = ctx.grid(sx, sy)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    k = sx * sy
    if ctx.p["color"] == "none":
        ink = ctx.ink(rgb, a)
        bits = binarize(ctx, ink)
        B = _cell_features(bits.astype(np.int64), sx, sy)
        code = (B * (1 << np.arange(k))[None, :]).sum(axis=1)
        chars = [char_of(int(c)) for c in code]
        arr = np.array(chars, dtype=object).reshape(rows, cols)
        return build_art(arr.tolist(), blank=ctx.blank(_cell_mean(a, sx, sy)))
    P = _cell_features(rgb, sx, sy)
    codes = list(range(1, 1 << k))
    M = np.array([[(c >> i) & 1 for i in range(k)] for c in codes], dtype=np.float64)
    gi, fg, bg = _fit_masks(P, M)
    code = np.array(codes, dtype=np.int64)[gi]
    full = code == (1 << k) - 1
    bg = np.where(full[:, None], fg, bg)
    chars = np.array([char_of(int(c)) for c in code], dtype=object).reshape(rows, cols)
    cm = "original" if ctx.p["color"] in ("none", "original") else None
    fgc = map_colors(ctx, fg.reshape(rows, cols, 3), cm)
    bgc = map_colors(ctx, bg.reshape(rows, cols, 3), cm)
    return build_art(chars.tolist(), fgc, bgc, ctx.blank(_cell_mean(a, sx, sy)))


def _fit_glyph_colors(ctx: Ctx, chars: list[str], fw: int, fh: int):
    """For each cell choose the glyph + fg/bg colours minimising ‖P − (m·fg + (1−m)·bg)‖² (least squares)."""
    rgb, a = ctx.grid(fw, fh)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    P = _cell_features(rgb, fw, fh)
    gi, fg, bg = _fit_masks(P, masks_float(chars, fw, fh))
    out = np.array(chars, dtype=object)[gi].reshape(rows, cols)
    cm = "original" if ctx.p["color"] in ("none", "original") else None
    fgc = map_colors(ctx, fg.reshape(rows, cols, 3), cm)
    bgc = map_colors(ctx, bg.reshape(rows, cols, 3), cm)
    return build_art(out.tolist(), fgc, bgc, ctx.blank(_cell_mean(a, fw, fh)))


def _edge_field(ctx: Ctx):
    """Edge magnitude (0..1, scaled by edge_strength) and orientation tensors at the working resolution."""
    if "edges" in ctx._cache:
        return ctx._cache["edges"]
    L = ctx.lum(ctx.flat())
    gx, gy = sobel(blur(L, 0.7))
    mag = np.sqrt(gx * gx + gy * gy) / 4.0 * ctx.p["edge_strength"]
    method = ctx.p["edge_method"]
    if method == "canny":
        e, _, _ = canny(L, ctx.p["edge_threshold"] * 0.5, ctx.p["edge_threshold"])
        mag = np.where(e, np.maximum(mag, ctx.p["edge_threshold"] + 1e-6), 0.0)
    elif method == "dog":
        d = blur(L, 1.0) - blur(L, 1.6)
        mag = np.clip(np.abs(d) * 12 * ctx.p["edge_strength"], 0, 1)
    ctx._cache["edges"] = (np.clip(mag, 0, 1), gx * gx, gy * gy, gx * gy)
    return ctx._cache["edges"]


def _orientation_chars(ctx: Ctx):
    """Per-cell edge strength and orientation glyph from the averaged structure tensor."""
    mag, jxx, jyy, jxy = _edge_field(ctx)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    M = resample_plane(mag, cols, rows)
    Jxx, Jyy, Jxy = (resample_plane(j, cols, rows) for j in (jxx, jyy, jxy))
    phi = 0.5 * np.arctan2(2 * Jxy, Jxx - Jyy)  # gradient direction, y down
    edge = (np.degrees(-phi) + 90.0) % 180.0     # edge direction, y up, 0..180
    glyph = np.where((edge < 31.5) | (edge >= 148.5), "-",
                     np.where(edge < 76.5, "/", np.where(edge < 103.5, "|", "\\"))).astype(object)
    return M, glyph


# ---------------------------------------------------------------------- the 30 modes
def m_classic(ctx):
    rgb, a = ctx.grid(1, 1)
    return _ramp(ctx, _palette(ctx, "classic"), ctx.ink(rgb, a), rgb, a)


def m_extended(ctx):
    chars, rgb, a = _shape_match(ctx, _palette(ctx, "extended"), 2, 2, 32)
    return apply_char_colors(ctx, chars.tolist(), rgb, ctx.blank(a))


def m_blocks(ctx):
    rgb, a = ctx.grid(1, 1)
    chars = resolve_palette(ctx.p["palette"] or "blocks", reverse=ctx.p["palette_reverse"])
    d = ctx.p["dither"] if ctx.p["dither"] != "none" else "floyd"
    return _ramp(ctx, chars, ctx.ink(rgb, a), rgb, a, d)


def m_half(ctx):
    rgb, a = ctx.grid(1, 2)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    top, bot = rgb[0::2], rgb[1::2]
    at, ab = a[0::2], a[1::2]
    if ctx.p["color"] == "none":
        bits = binarize(ctx, ctx.ink(rgb, a))
        code = bits[0::2].astype(np.int64) | (bits[1::2].astype(np.int64) << 1)
        chars = np.array(list(" ▀▄█"), dtype=object)[code]
        return build_art(chars.tolist())
    fg = map_colors(ctx, top)
    bgc = map_colors(ctx, bot)
    chars = np.full((rows, cols), "▀", dtype=object)
    if ctx.p["transparent_bg"]:
        tt, tb = at < 0.5, ab < 0.5
        chars = np.where(tt & tb, " ", np.where(tt, "▄", chars))
        fg2 = np.where(tt, bgc, fg)
        bg2 = np.where(tt | tb, -1, bgc)
        art = build_art(chars.tolist(), fg2, None)
        bl = bg2.tolist()
        art.bg = [[None if v < 0 else v for v in r] for r in bl]
        for y in range(rows):
            for x in range(cols):
                if chars[y, x] == " ":
                    art.fg[y][x] = None
        return art
    return build_art(chars.tolist(), fg, bgc)


def m_quadrant(ctx):
    return _two_color_patterns(ctx, 2, 2, lambda c: QUADRANT_CHARS[c])


def m_sextant(ctx):
    return _two_color_patterns(ctx, 2, 3, sextant_char)


def m_braille(ctx):
    rgb, a = ctx.grid(2, 4)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    ink = ctx.ink(rgb, a)
    on = binarize(ctx, ink)
    if ctx.p["transparent_bg"]:
        on &= a >= 0.5
    code = np.zeros((rows, cols), dtype=np.int64)
    for bit, (dx, dy) in enumerate(BRAILLE_DOTS):
        code |= on[dy::4, dx::2].astype(np.int64) << bit
    chars = np.vectorize(lambda c: chr(0x2800 + int(c)), otypes=[object])(code)
    if ctx.p["color"] == "none":
        return build_art(chars.tolist())
    F = _cell_features(rgb, 2, 4)
    O = _cell_features(on.astype(np.float64), 2, 4)
    cnt = O.sum(axis=1)
    mean_on = (F * O[:, :, None]).sum(axis=1) / np.maximum(cnt, 1)[:, None]
    mean_all = F.mean(axis=1)
    col = np.where((cnt > 0)[:, None], mean_on, mean_all).reshape(rows, cols, 3)
    return apply_char_colors(ctx, chars.tolist(), col, None)


def _palette_diffuse(rgb, palette: list[int], dither: str, strength: float):
    """Error diffusion in RGB with nearest-palette selection in CIELAB (cached per exact colour)."""
    H, W = rgb.shape[:2]
    pal = np.array([int_to_rgb01(c) for c in palette])
    plab = rgb_to_lab(pal).tolist()
    pal_l = pal.tolist()
    cache: dict = {}
    _lab = rgb_to_lab  # bundled import

    def nearest(r, g, b):
        key = (int(r * 255 + 0.5) if r > 0 else 0, int(g * 255 + 0.5) if g > 0 else 0, int(b * 255 + 0.5) if b > 0 else 0)
        key = (min(255, key[0]), min(255, key[1]), min(255, key[2]))
        if key in cache:
            return cache[key]
        lab = _lab(np.array([key[0] / 255, key[1] / 255, key[2] / 255])).tolist()
        bi, bd = 0, float("inf")
        for i, q in enumerate(plab):
            d = (lab[0] - q[0]) ** 2 + (lab[1] - q[1]) ** 2 + (lab[2] - q[2]) ** 2
            if d < bd:
                bd, bi = d, i
        cache[key] = bi
        return bi
    g = rgb.tolist()
    out = [[0] * W for _ in range(H)]
    taps = ((1, 0, 7 / 16), (-1, 1, 3 / 16), (0, 1, 5 / 16), (1, 1, 1 / 16)) if dither == "floyd" else \
        ((1, 0, 1 / 8), (2, 0, 1 / 8), (-1, 1, 1 / 8), (0, 1, 1 / 8), (1, 1, 1 / 8), (0, 2, 1 / 8))
    for y in range(H):
        for x in range(W):
            r, gg, b = g[y][x]
            i = nearest(r, gg, b)
            out[y][x] = palette[i]
            q = pal_l[i]
            er, eg, eb = (r - q[0]) * strength, (gg - q[1]) * strength, (b - q[2]) * strength
            for dx, dy, f in taps:
                xx, yy = x + dx, y + dy
                if 0 <= xx < W and yy < H:
                    c = g[yy][xx]
                    g[yy][xx] = [c[0] + er * f, c[1] + eg * f, c[2] + eb * f]
    return np.array(out, dtype=np.int64)


def _half_from_colors(ctx, colors, a):
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    fg, bgc = colors[0::2], colors[1::2]
    chars = np.full((rows, cols), "▀", dtype=object)
    blank = ctx.blank(np.maximum(a[0::2], a[1::2]))
    return build_art(chars.tolist(), fg, bgc, blank)


def _ansi_palette_mode(ctx, palette, default_dither):
    rgb, a = ctx.grid(1, 2)
    d = ctx.p["dither"] if ctx.p["dither"] != "none" else default_dither
    if d in ("floyd", "atkinson"):
        colors = _palette_diffuse(rgb, palette, d, ctx.p["dither_strength"])
    else:
        colors = _nearest_palette(rgb, palette)
    return _half_from_colors(ctx, colors, a)


def m_ansi16(ctx):
    return _ansi_palette_mode(ctx, ANSI16_RGB, "floyd")


def m_ansi256(ctx):
    return _ansi_palette_mode(ctx, xterm256(), "none")


def m_truecolor(ctx):
    rgb, a = ctx.grid(1, 2)
    return _half_from_colors(ctx, rgb01_to_int(rgb), a)


def m_mono(ctx):
    rgb, a = ctx.grid(1, 2)
    ink = ctx.ink(rgb, a)
    d = ctx.p["dither"] if ctx.p["dither"] != "none" else "floyd"
    if ctx.p["adaptive"]:
        bits = adaptive_mask(ink, ctx.p["threshold"])
    else:
        bits = quantize_levels(ink, [0.0, 1.0], d, ctx.p["dither_strength"]) == 1
    code = bits[0::2].astype(np.int64) | (bits[1::2].astype(np.int64) << 1)
    return build_art(np.array(list(" ▀▄█"), dtype=object)[code].tolist())


def m_grayscale(ctx):
    rgb, a = ctx.grid(1, 2)
    L = ctx.lum(rgb)
    levels = [((c >> 16) & 255) / 255 for c in GRAY26]
    d = ctx.p["dither"] if ctx.p["dither"] != "none" else "bayer"
    q = quantize_levels(L, levels, d, ctx.p["dither_strength"])
    colors = np.array(GRAY26, dtype=np.int64)[q]
    return _half_from_colors(ctx, colors, a)


def m_binary(ctx):
    rgb, a = ctx.grid(1, 1)
    ink = ctx.ink(rgb, a)
    r = max(2, min(ink.shape) // 10)
    mean = box_mean(ink, r)
    t = ctx.p["threshold"]
    hi = ink > np.maximum(mean, t)
    lo = ink > np.minimum(mean, t) * 0.5
    chars = np.where(hi, "1", np.where(lo, "0", " ")).astype(object)
    return apply_char_colors(ctx, chars.tolist(), rgb, ctx.blank(a))


def m_matrix(ctx):
    rgb, a = ctx.grid(1, 1)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    L = ctx.lum(rgb)
    if not ctx.p["light_on_dark"]:
        L = 1 - L
    rng = Rng(ctx.p["seed"])
    glyphs = graphemes_simple(MATRIX_GLYPHS)
    heads = [rng.int(rows + 8) for _ in range(cols)]
    trail = [4 + rng.int(max(4, rows // 2)) for _ in range(cols)]
    chars = [[" "] * cols for _ in range(rows)]
    fg = [[None] * cols for _ in range(rows)]
    Ll = L.tolist()
    blank = ctx.blank(a).tolist()
    for y in range(rows):
        for x in range(cols):
            v = Ll[y][x]
            g = glyphs[rng.int(len(glyphs))]
            if v < 0.08 or blank[y][x]:
                continue
            d = heads[x] - y
            boost = 1.0 if d == 0 else (0.35 * (1 - d / trail[x]) if 0 < d < trail[x] else 0.0)
            chars[y][x] = g
            gl = min(1.0, v * 0.9 + boost * 0.5)
            if d == 0:
                fg[y][x] = (int(180 + 75 * gl) << 16) | (255 << 8) | int(180 + 75 * gl)
            else:
                fg[y][x] = (int(30 * gl) << 16) | (int(60 + 195 * gl) << 8) | int(40 * gl)
    return Art(chars, fg, [[None] * cols for _ in range(rows)])


def m_emoji(ctx):
    rgb, a = ctx.grid(1, 1)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    spec = ctx.p["palette"]
    if spec and spec != "emoji":
        allowed = set(graphemes_simple(spec))
        pal = [(e, c) for e, c in EMOJI_COLORS if e in allowed] or EMOJI_COLORS
    else:
        pal = EMOJI_COLORS
    picked = _nearest_palette(rgb, [c for _, c in pal])
    by_color = {}
    for e, c in pal:
        by_color.setdefault(c, e)
    blank = ctx.blank(a).tolist()
    pk = picked.tolist()
    chars = []
    for y in range(rows):
        r = []
        for x in range(cols):
            if blank[y][x]:
                r += [" ", " "]
            else:
                r += [by_color[pk[y][x]], ""]
        chars.append(r)
    return Art(chars)


def m_pixel(ctx):
    rgb, a = ctx.grid(1, 1)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    mode = ctx.p["color"]
    if mode in ("none", "original"):
        k = ctx.p["dominant_k"] if mode == "none" else 0
        colors = _nearest_palette(rgb, [int(r * 255 + 0.5) << 16 | int(g * 255 + 0.5) << 8 | int(b * 255 + 0.5)
                                        for r, g, b in median_cut(ctx.flat(), max(2, k or 16))]) if k else rgb01_to_int(rgb)
    else:
        colors = map_colors(ctx, rgb)
    blank = ctx.blank(a)
    c2 = np.repeat(colors, 2, axis=1)
    chars = np.where(np.repeat(blank, 2, axis=1), " ", "█").astype(object)
    return build_art(chars.tolist(), c2, None, np.repeat(blank, 2, axis=1))


def m_dotted(ctx):
    rgb, a = ctx.grid(1, 1)
    chars = resolve_palette(ctx.p["palette"] or "dots", reverse=ctx.p["palette_reverse"])
    levels = density_levels(chars)
    ink = ctx.ink(rgb, a)
    H, W = ink.shape
    n = len(levels)
    # 45° clustered screen: alternate cells are offset by half a level (classic AM halftone look)
    off = np.where((np.arange(H)[:, None] + np.arange(W)[None, :]) % 2 == 0, -0.25, 0.25) / max(1, n - 1)
    q = quantize_levels(np.clip(ink + off, 0, 1), levels, "none")
    arr = np.array(chars, dtype=object)[q]
    return apply_char_colors(ctx, arr.tolist(), rgb, ctx.blank(a))


def m_edge(ctx):
    rgb, a = ctx.grid(1, 1)
    M, glyph = _orientation_chars(ctx)
    chars = np.where(M >= ctx.p["edge_threshold"] * 0.5, glyph, " ").astype(object)
    return apply_char_colors(ctx, chars.tolist(), rgb, ctx.blank(a))


CONTOUR_CHARS = {1: "╯", 2: "╰", 4: "╭", 8: "╮", 3: "─", 12: "─", 9: "│", 6: "│", 5: "╳", 10: "╳"}


def m_contour(ctx):
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    L = ctx.lum(ctx.flat())
    Lc = resample_plane(blur(L, 1.0), cols + 1, rows + 1)
    n = ctx.p["levels"]
    band = np.clip(np.floor(Lc * n), 0, n - 1).astype(np.int64)
    tl, tr, br, bl = band[:-1, :-1], band[:-1, 1:], band[1:, 1:], band[1:, :-1]
    mx = np.maximum(np.maximum(tl, tr), np.maximum(br, bl))
    mask = (tl == mx).astype(np.int64) | ((tr == mx).astype(np.int64) << 1) | ((br == mx).astype(np.int64) << 2) | ((bl == mx).astype(np.int64) << 3)
    pc = np.vectorize(lambda m: bin(int(m)).count("1"))(mask)
    mask = np.where(pc > 2, 15 - mask, mask)
    chars = np.vectorize(lambda m: CONTOUR_CHARS.get(int(m), " "), otypes=[object])(mask)
    rgb, a = ctx.grid(1, 1)
    if ctx.p["color"] == "none":
        return build_art(chars.tolist(), blank=ctx.blank(a))
    if ctx.p["color"] == "gradient":
        stops = parse_color_list(ctx.p["gradient"]) or [0, 0xFFFFFF]
        lut = np.array([gradient_color(stops, i / max(1, n - 1)) for i in range(n)], dtype=np.int64)
        return build_art(chars.tolist(), lut[mx], None, ctx.blank(a))
    return apply_char_colors(ctx, chars.tolist(), rgb, ctx.blank(a))


def m_line(ctx):
    rgb, a = ctx.grid(4, 8)
    L = ctx.lum(ctx.flat())
    s = max(0.6, ctx.work.width / (ctx.g["gcols"] * 4) * 0.6)
    d = blur(L, s) - blur(L, s * 1.6)
    lines = np.clip(-d * 40 * ctx.p["edge_strength"] - ctx.p["edge_threshold"], 0, 1)
    lw = resample_plane(lines, ctx.g["gcols"] * 4, ctx.g["rows"] * 8)
    if ctx.p["transparent_bg"]:
        lw = np.where(a < 0.5, 0.0, lw)
    chars, crgb, ca = _shape_match(ctx, _palette(ctx, "line"), 4, 8, 18, ink=lw)
    return apply_char_colors(ctx, chars.tolist(), crgb, None)


def foreground_mask(ctx: Ctx):
    """Foreground: alpha where the image is transparent, else the Otsu class not dominating the border."""
    work = ctx.work
    if (work.a < 0.5).mean() > 0.01:
        return work.a >= 0.5
    L = ctx.lum(ctx.flat())
    t = otsu(L)
    dark = L < t
    border = np.concatenate([dark[0], dark[-1], dark[:, 0], dark[:, -1]])
    return dark if border.mean() < 0.5 else ~dark


def m_silhouette(ctx):
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    fgm = foreground_mask(ctx).astype(np.float64)
    m = resample_plane(fgm, cols * 2, rows * 2) >= 0.5
    B = _cell_features(m.astype(np.int64), 2, 2)
    code = (B * np.array([1, 2, 4, 8])[None, :]).sum(axis=1).reshape(rows, cols)
    chars = np.array(list(QUADRANT_CHARS), dtype=object)[code]
    rgb, a = ctx.grid(1, 1)
    return apply_char_colors(ctx, chars.tolist(), rgb, None)


def m_typographic(ctx):
    chars, rgb, a = _shape_match(ctx, _palette(ctx, "typographic"), 4, 8, 24)
    return apply_char_colors(ctx, chars.tolist(), rgb, ctx.blank(a))


def _text_stream(text: str, direction: str):
    pass  # bundled import
    pass  # bundled import
    text = " ".join(clean_palette(text).split()) or "LeerBox"
    rtl = direction == "rtl" or (direction == "auto" and paragraph_level(text, "auto") == 1)
    if contains_arabic(text):
        text = shape(text)
    gs = graphemes_simple(text + " ")
    return [(g, max(1, char_width(g))) for g in gs], rtl


def m_words(ctx):
    rgb, a = ctx.grid(1, 1)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    ink = ctx.ink(rgb, a)
    p = ctx.p
    stream, rtl = _text_stream(p["text"], p["text_dir"])
    words = []
    cur = []
    for g, w in stream:
        cur.append((g, w))
        if g == " ":
            words.append(cur); cur = []
    if cur:
        words.append(cur)
    on = (ink >= p["threshold"] * 0.6) if p["text_mode"] != "fill" else np.ones(ink.shape, dtype=bool)
    if p["transparent_bg"]:
        on &= a >= 0.5
    onl = on.tolist()
    chars = [[" "] * cols for _ in range(rows)]
    si, wi = 0, 0
    for y in range(rows):
        xs = list(range(cols - 1, -1, -1)) if rtl else list(range(cols))
        if p["text_mode"] == "words":
            k = 0
            while k < len(xs):
                if not onl[y][xs[k]]:
                    k += 1; continue
                run = 0
                while k + run < len(xs) and onl[y][xs[k + run]]:
                    run += 1
                pos = k
                while True:
                    word = words[wi % len(words)]
                    wl = sum(w for _, w in word)
                    if pos + wl - (1 if word[-1][0] == " " else 0) > k + run:
                        break
                    for g, w in word:
                        if pos >= k + run:
                            break
                        if w == 2 and pos + 1 < k + run:
                            if rtl:
                                chars[y][xs[pos + 1]] = g; chars[y][xs[pos]] = ""
                            else:
                                chars[y][xs[pos]] = g; chars[y][xs[pos + 1]] = ""
                            pos += 2
                        elif w == 1:
                            chars[y][xs[pos]] = g; pos += 1
                        else:
                            pos += 1
                    wi += 1
                for j in range(pos, k + run):
                    chars[y][xs[j]] = "·"
                k += run
        else:
            k = 0
            while k < len(xs):
                if not onl[y][xs[k]]:
                    k += 1; continue
                g, w = stream[si % len(stream)]
                if w == 2:
                    if k + 1 < len(xs) and onl[y][xs[k + 1]]:
                        if rtl:
                            chars[y][xs[k + 1]] = g; chars[y][xs[k]] = ""
                        else:
                            chars[y][xs[k]] = g; chars[y][xs[k + 1]] = ""
                        k += 2; si += 1
                    else:
                        k += 1
                    continue
                chars[y][xs[k]] = g
                k += 1; si += 1
    art = apply_char_colors(ctx, chars, rgb, None)
    if ctx.p["color"] == "none" and p["text_mode"] == "fill":
        # without colour the 'fill' layout encodes luminance by case: dense regions upper-case
        il = ink.tolist()
        for y in range(rows):
            for x in range(cols):
                c = art.chars[y][x]
                if len(c) == 1 and il[y][x] < 0.35:
                    art.chars[y][x] = c.lower() if il[y][x] >= 0.12 else ("." if c.strip() else c)
                elif len(c) == 1:
                    art.chars[y][x] = c.upper()
    return art


def m_math(ctx):
    chars, rgb, a = _shape_match(ctx, _palette(ctx, "math"), 4, 8, 16)
    return apply_char_colors(ctx, chars.tolist(), rgb, ctx.blank(a))


MOSAIC_GLYPHS = [" ", "█", "▀", "▄", "▌", "▐", "◢", "◣", "◤", "◥", "●", "◆", "▲", "▼", "■", "◖", "◗"]


def _available(chars):
    pass  # bundled import
    return [c for c in chars if glyph_mask(c) is not None]


def m_mosaic(ctx):
    return _fit_glyph_colors(ctx, _available(MOSAIC_GLYPHS), 4, 8)


DENSE_GLYPHS = ([" ", "█", "▀", "▄", "▌", "▐", "▖", "▗", "▘", "▝", "▚", "▞", "▙", "▛", "▜", "▟"]
                + [chr(c) for c in range(0x2581, 0x2588)] + [chr(c) for c in range(0x2589, 0x2590)]
                + [chr(c) for c in range(0x1FB00, 0x1FB3C)])


def m_dense(ctx):
    return _fit_glyph_colors(ctx, DENSE_GLYPHS, 4, 8)


def m_adaptive(ctx):
    rgb, a = ctx.grid(4, 8)
    ink = ctx.ink(rgb, a)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    feats = _cell_features(ink, 4, 8)
    std = feats.std(axis=1).reshape(rows, cols)
    chars = _palette(ctx, "adaptive")
    shaped, crgb, ca = _shape_match(ctx, chars, 4, 8, 24, ink=ink)
    mean_ink = feats.mean(axis=1).reshape(rows, cols)
    levels = density_levels(chars)
    q = quantize_levels(mean_ink, levels, ctx.p["dither"], ctx.p["dither_strength"])
    ramp = np.array(chars, dtype=object)[q]
    detail = std > 0.12 + (ctx.p["edge_threshold"] - 0.25) * 0.3
    out = np.where(detail, shaped, ramp)
    return apply_char_colors(ctx, out.tolist(), crgb, ctx.blank(ca))


def m_hybrid(ctx):
    rgb, a = ctx.grid(1, 1)
    chars = _palette(ctx, "hybrid")
    q = quantize_levels(ctx.ink(rgb, a), density_levels(chars), ctx.p["dither"], ctx.p["dither_strength"])
    base = np.array(chars, dtype=object)[q]
    M, glyph = _orientation_chars(ctx)
    out = np.where(M >= ctx.p["edge_threshold"], glyph, base)
    return apply_char_colors(ctx, out.tolist(), rgb, ctx.blank(a))


def m_negative(ctx):
    rgb, a = ctx.grid(1, 1)
    pass  # bundled import
    neg = linear_to_srgb(1.0 - srgb_to_linear(rgb))
    L = luminance(neg, "perceptual")
    ink = L if ctx.p["light_on_dark"] else 1 - L
    if ctx.p["transparent_bg"]:
        ink = np.where(a < 0.5, 0.0, ink)
    chars = _palette(ctx, "negative")
    q = quantize_levels(np.clip(ink, 0, 1), density_levels(chars), ctx.p["dither"], ctx.p["dither_strength"])
    return apply_char_colors(ctx, np.array(chars, dtype=object)[q].tolist(), neg, ctx.blank(a))


def m_multilayer(ctx):
    rgb, a = ctx.grid(4, 8)
    rows, cols = ctx.g["rows"], ctx.g["gcols"]
    cm = _cell_mean_rgb(rgb, 4, 8)
    low_c = blur(cm, 1.5)                                   # layer 1: low-pass colour
    L = ctx.lum(rgb)
    det = _cell_mean(np.abs(L - blur(L, 3.0)), 4, 8)         # layer 2: high-pass luminance detail
    det_n = np.clip(det * 6, 0, 1)
    chars = _palette(ctx, "multilayer")
    q = quantize_levels(det_n, density_levels(chars), "none")
    mid = np.array(chars, dtype=object)[q]
    M, glyph = _orientation_chars(ctx)                       # layer 3: edges
    edge = M >= ctx.p["edge_threshold"]
    out = np.where(edge, glyph, mid)
    bgc = rgb01_to_int(low_c * 0.55)
    fgc = rgb01_to_int(np.clip(cm * 1.25 + 0.08, 0, 1))
    fgc = np.where(edge, rgb01_to_int(np.clip(cm * 0.5 + 0.5, 0, 1)), fgc)
    if ctx.p["color"] not in ("none", "original"):
        fgc = map_colors(ctx, cm)
        bgc = map_colors(ctx, low_c * 0.55)
    art = build_art(out.tolist(), fgc, bgc, ctx.blank(_cell_mean(a, 4, 8)))
    art.meta["layers"] = ["background: low-pass colour", "detail: high-pass luminance glyphs", "edges: orientation glyphs"]
    return art


RENDERERS = {
    "classic": m_classic, "extended": m_extended, "blocks": m_blocks, "half": m_half, "quadrant": m_quadrant,
    "sextant": m_sextant, "braille": m_braille, "ansi16": m_ansi16, "ansi256": m_ansi256, "truecolor": m_truecolor,
    "mono": m_mono, "grayscale": m_grayscale, "binary": m_binary, "matrix": m_matrix, "emoji": m_emoji,
    "pixel": m_pixel, "dotted": m_dotted, "edge": m_edge, "contour": m_contour, "line": m_line,
    "silhouette": m_silhouette, "typographic": m_typographic, "words": m_words, "math": m_math,
    "mosaic": m_mosaic, "dense": m_dense, "adaptive": m_adaptive, "hybrid": m_hybrid, "negative": m_negative,
    "multilayer": m_multilayer,
}
assert set(RENDERERS) == set(MODES)


class RenderCancelled(Exception):
    pass


def render_image_art(src: RasterImage, params: dict | None = None, cancel=None) -> tuple[Art, dict]:
    """Full pipeline: sanitize → prepare → mode renderer. Returns (art, stats)."""
    require_numpy()
    p = sanitize_params(params)
    t0 = time.perf_counter()
    work, g = prepare(src, p)
    if cancel is not None and cancel():
        raise RenderCancelled()
    ctx = Ctx(work, g, p)
    art = RENDERERS[p["mode"]](ctx)
    if cancel is not None and cancel():
        raise RenderCancelled()
    art.meta["image_mode"] = p["mode"]
    dt = (time.perf_counter() - t0) * 1000
    txt_bytes = sum(len("".join(r).rstrip().encode("utf-8")) + 1 for r in art.chars)
    stats = {"mode": p["mode"], "label": MODES[p["mode"]][0], "cols": art.width, "rows": art.height,
             "chars": art.width * art.height, "source": [src.width, src.height], "work": [work.width, work.height],
             "ms": round(dt, 1), "text_bytes": txt_bytes, "compat": COMPAT_NOTES[MODES[p["mode"]][5]],
             "est_memory_bytes": work.width * work.height * 8 * 6 + art.width * art.height * 120}
    return art, stats


# ==========================================================================
# module: leerbox/imganalysis.py
# ==========================================================================
"""Image analysis, recommendations, reconstruction metrics and Smart Optimize.

Everything here is deterministic signal processing and simple rules — no machine learning. The quality
metrics (luminance RMSE, SSIM, edge correlation, CIELAB ΔE, size) are approximations of visual quality.
"""

import time


# ---------------------------------------------------------------------- analysis
ORIENT_NAMES = ["horizontal", "diagonal ↗", "vertical", "diagonal ↘"]


def analyze(src: RasterImage) -> dict:
    """Measure the image and derive recommended settings (each with a reason)."""
    require_numpy()
    s = min(1.0, 384 / max(src.width, src.height))
    work = resample_area(src, max(8, round(src.width * s)), max(8, round(src.height * s)))
    flat = composite(work, 0xFFFFFF)
    L = luminance(flat)
    H, W = L.shape
    pct = np.percentile(L, [1, 5, 50, 95, 99])
    hist = np.bincount(np.clip((L * 16).astype(np.int64), 0, 15).ravel(), minlength=16) / L.size
    r, g, b = flat[..., 0] * 255, flat[..., 1] * 255, flat[..., 2] * 255
    rg, yb = r - g, 0.5 * (r + g) - b
    colorfulness = float(np.sqrt(rg.std() ** 2 + yb.std() ** 2) + 0.3 * np.sqrt(rg.mean() ** 2 + yb.mean() ** 2))
    gx, gy = sobel(L)
    mag = np.hypot(gx, gy) / 4
    edge_density = float((mag > 0.1).mean())
    local_std = np.sqrt(np.maximum(box_mean(L * L, 2) - box_mean(L, 2) ** 2, 0))
    texture = float(local_std.mean())
    detail = float(np.abs(L - blur(L, 1.0)).mean())
    t = otsu(L)
    lo, hi = L[L < t], L[L >= t]
    var = float(L.var()) or 1e-9
    between = (lo.size * hi.size / L.size ** 2) * ((hi.mean() if hi.size else 0) - (lo.mean() if lo.size else 0)) ** 2
    separation = float(between / var)
    border = np.concatenate([L[0], L[-1], L[:, 0], L[:, -1]])
    center = L[H // 4:3 * H // 4, W // 4:3 * W // 4]
    border_contrast = float(abs(border.mean() - center.mean()))
    alpha_frac = float((work.a < 0.5).mean())
    partial_alpha = float(((work.a > 0.02) & (work.a < 0.98)).mean())
    pal = median_cut(flat, 6)
    labs = rgb_to_lab(np.array(pal))
    flab = rgb_to_lab(flat.reshape(-1, 3)[::max(1, L.size // 20000)])
    near = np.argmin(((flab[:, None, :] - labs[None, :, :]) ** 2).sum(axis=2), axis=1)
    share = np.bincount(near, minlength=len(pal)) / len(near)
    dominant = sorted(({"color": "#%02x%02x%02x" % tuple(int(round(v * 255)) for v in c), "share": round(float(sh), 3)}
                       for c, sh in zip(pal, share)), key=lambda d: -d["share"])
    grid = [[round(float(L[i * H // 4:(i + 1) * H // 4, j * W // 4:(j + 1) * W // 4].mean()), 3) for j in range(4)]
            for i in range(4)]
    ang = (np.degrees(np.arctan2(-gy, gx)) + 90.0) % 180.0
    ob = np.bincount(np.clip(((ang + 22.5) % 180 / 45).astype(np.int64), 0, 3).ravel(), weights=mag.ravel(), minlength=4)
    ob = ob / max(1e-9, ob.sum())
    unique_colors = int(len(np.unique((np.floor(flat.reshape(-1, 3) * 15.99)).astype(np.int64) @ np.array([256, 16, 1]))))
    metrics = {
        "width": src.width, "height": src.height, "aspect": round(src.width / src.height, 4),
        "mean_luminance": round(float(L.mean()), 4), "luminance_std": round(float(L.std()), 4),
        "percentiles": {k: round(float(v), 4) for k, v in zip(("p1", "p5", "p50", "p95", "p99"), pct)},
        "dynamic_range": round(float(pct[4] - pct[0]), 4), "histogram16": [round(float(v), 4) for v in hist],
        "colorfulness": round(colorfulness, 2), "edge_density": round(edge_density, 4),
        "texture": round(texture, 4), "detail": round(detail, 4), "otsu_threshold": round(t, 4),
        "fg_bg_separation": round(separation, 4), "border_contrast": round(border_contrast, 4),
        "transparent_fraction": round(alpha_frac, 4), "partial_alpha_fraction": round(partial_alpha, 4),
        "dominant_colors": dominant, "local_luminance_4x4": grid,
        "gradient_orientation": {n: round(float(v), 3) for n, v in zip(ORIENT_NAMES, ob)},
        "quantized_colors_4bit": unique_colors,
    }
    return {"metrics": metrics, "recommendations": recommend_settings(metrics)}


def recommend_settings(m: dict) -> list[dict]:
    """Rule-based recommendations. Every item: {key, value, reason}; apply with recommended_params()."""
    rec = []

    def add(key, value, reason):
        rec.append({"key": key, "value": value, "reason": reason})
    logo = m["fg_bg_separation"] > 0.75 and m["quantized_colors_4bit"] < 400 and m["texture"] < 0.08
    colorful = m["colorfulness"] > 35
    transparent = m["transparent_fraction"] > 0.05
    if transparent and logo:
        add("mode", "silhouette", "transparent background and few flat colours → crisp silhouette")
    elif logo and colorful:
        add("mode", "sextant", "flat-colour logo/graphic → sextant blocks with fitted colours keep edges sharp")
    elif logo:
        add("mode", "quadrant", "high-contrast graphic with clear figure/ground → quadrant blocks")
    elif colorful:
        add("mode", "truecolor", f"colourful image (colourfulness {m['colorfulness']:.0f}) → half-block true colour")
    elif m["detail"] > 0.035:
        add("mode", "braille", "fine detail without much colour → Braille gives 8 dots per cell")
    else:
        add("mode", "classic", "smooth monochrome image → density-mapped ASCII reads well")
    cols = 80
    if m["detail"] > 0.05 or m["edge_density"] > 0.25:
        cols = 140
    elif m["detail"] > 0.025:
        cols = 110
    elif m["detail"] < 0.01:
        cols = 60
    if m["aspect"] > 1.6:
        cols = int(cols * 1.25)
    add("cols", min(300, cols), f"detail {m['detail']:.3f}, edge density {m['edge_density']:.2f}, aspect {m['aspect']:.2f}")
    if m["dynamic_range"] < 0.55:
        add("equalize", "clahe", f"narrow luminance range ({m['dynamic_range']:.2f}) → adaptive histogram equalization")
    elif m["dynamic_range"] < 0.8:
        add("contrast", round(min(2.0, 0.9 / max(0.2, m["dynamic_range"])), 2), "moderate range → stretch contrast")
    if m["mean_luminance"] < 0.3:
        add("shadows", 0.4, "dark image → lift shadows")
    elif m["mean_luminance"] > 0.78:
        add("highlights", -0.4, "bright image → recover highlights")
    add("palette", "ascii_high" if m["texture"] > 0.06 else "ascii_extended",
        "textured image → larger glyph set" if m["texture"] > 0.06 else "smooth image → measured 70-glyph ramp")
    add("edge_strength", 1.6 if m["edge_density"] < 0.06 else (0.8 if m["edge_density"] > 0.3 else 1.0),
        f"edge density {m['edge_density']:.2f}")
    add("color", "none" if m["colorfulness"] < 8 else ("ansi256" if m["colorfulness"] < 30 else "original"),
        f"colourfulness {m['colorfulness']:.0f}: " + ("practically grey" if m["colorfulness"] < 8 else
                                                       "moderate → 256 colours suffice" if m["colorfulness"] < 30 else
                                                       "rich colour → keep original colours"))
    smooth = m["texture"] < 0.05 and m["dynamic_range"] > 0.5
    add("dither", "none" if logo else ("floyd" if smooth else "atkinson"),
        "flat graphic: dithering would add noise" if logo else
        "smooth gradients → Floyd–Steinberg avoids banding" if smooth else "textured → Atkinson keeps contrast")
    if transparent:
        add("transparent_bg", True, f"{m['transparent_fraction'] * 100:.0f}% transparent pixels stay empty")
    return rec


def recommended_params(analysis: dict, base: dict | None = None) -> dict:
    p = dict(base or {})
    for r in analysis["recommendations"]:
        p[r["key"]] = r["value"]
    return sanitize_params(p)


# ---------------------------------------------------------------------- reconstruction & metrics
BLOCK_LIKE = set(range(0x2580, 0x25A0)) | set(range(0x1FB00, 0x1FB3C))


def reconstruct(art: Art, p: dict, fw: int = 4, fh: int = 8):
    """Simulated display of the art at fw×fh samples per cell → (rgb H×W×3), vectorised."""
    rows, cols = art.height, art.width
    lod = p.get("light_on_dark", True)
    dfg, dbg = ((0xEBEBEB, 0x0D0D0D) if lod else (0x0D0D0D, 0xF7F7F7))
    emoji = dict(EMOJI_COLORS)
    chars = [list(r) for r in art.chars]
    fgs = [list(r) for r in art.fg]
    bgs = [list(r) for r in art.bg]
    for y in range(rows):  # continuation cells repeat the wide glyph's left half
        for x in range(1, cols):
            if chars[y][x] == "":
                chars[y][x], fgs[y][x], bgs[y][x] = chars[y][x - 1], fgs[y][x - 1], bgs[y][x - 1]
    uniq = sorted({c for r in chars for c in r})
    index = {c: i for i, c in enumerate(uniq)}
    masks, text_max = [], 0.0
    for c in uniq:
        m = glyph_mask(c) if c not in emoji else None
        if c in emoji:
            arr = np.ones((fh, fw))
        elif m is None:
            arr = np.full((fh, fw), 0.2)
        else:
            arr = (np.frombuffer(m, dtype=np.uint8).astype(np.float64).reshape(16, 8) / 255
                   ).reshape(fh, 16 // fh, fw, 8 // fw).mean(axis=(1, 3))
        if c not in emoji and len(c) == 1 and ord(c) not in BLOCK_LIKE and c.strip():
            text_max = max(text_max, float(arr.mean()))
        masks.append(arr)
    norm = 1.0 / text_max if 0 < text_max < 0.8 else 1.0
    for i, c in enumerate(uniq):
        if c not in emoji and len(c) == 1 and ord(c) not in BLOCK_LIKE:
            masks[i] = np.clip(masks[i] * norm, 0, 1)
    M = np.array(masks)
    idx = np.array([[index[c] for c in r] for r in chars], dtype=np.int64)
    fgi = np.array([[(emoji[c] if c in emoji else (f if f is not None else dfg)) for c, f in zip(rc, rf)]
                    for rc, rf in zip(chars, fgs)], dtype=np.int64)
    bgi = np.array([[b if b is not None else dbg for b in r] for r in bgs], dtype=np.int64)

    def rgb(a):
        return np.stack([(a >> 16) & 255, (a >> 8) & 255, a & 255], axis=-1) / 255.0
    F, B = rgb(fgi), rgb(bgi)
    mm = M[idx][..., None]  # rows, cols, fh, fw, 1
    out = mm * F[:, :, None, None, :] + (1 - mm) * B[:, :, None, None, :]
    return out.transpose(0, 2, 1, 3, 4).reshape(rows * fh, cols * fw, 3)


def _ssim(a, b):
    c1, c2 = 0.01 ** 2, 0.03 ** 2
    mu_a, mu_b = blur(a, 1.5), blur(b, 1.5)
    va = blur(a * a, 1.5) - mu_a ** 2
    vb = blur(b * b, 1.5) - mu_b ** 2
    cov = blur(a * b, 1.5) - mu_a * mu_b
    s = ((2 * mu_a * mu_b + c1) * (2 * cov + c2)) / ((mu_a ** 2 + mu_b ** 2 + c1) * (va + vb + c2))
    return float(s.mean())


def quality_metrics(reference_rgb, rec_rgb, size_bytes: int) -> dict:
    """Compare a reconstruction with the reference at the same resolution (both blurred: viewing distance)."""
    ra, rb = blur(reference_rgb, 1.0), blur(rec_rgb, 1.0)
    la, lb = luminance(ra), luminance(rb)
    rmse = float(np.sqrt(((la - lb) ** 2).mean()))
    ssim = _ssim(la, lb)
    ga = np.hypot(*sobel(la)); gb = np.hypot(*sobel(lb))
    sa, sb = ga - ga.mean(), gb - gb.mean()
    den = float(np.sqrt((sa * sa).sum() * (sb * sb).sum()))
    edge = float((sa * sb).sum() / den) if den > 1e-12 else 0.0
    de = float(np.sqrt(((rgb_to_lab(ra) - rgb_to_lab(rb)) ** 2).sum(axis=-1)).mean())
    return {"lum_rmse": round(rmse, 4), "ssim": round(ssim, 4), "edge_corr": round(edge, 4),
            "color_de": round(de, 2), "bytes": int(size_bytes)}


def evaluate(src: RasterImage, art: Art, p: dict) -> dict:
    p = sanitize_params(p)
    work, g = prepare(src, p)
    fw, fh = 4, 8
    rows, cols = art.height, art.width
    ref = resample_area(work, cols * fw, rows * fh)
    bg = np.array([0.05, 0.05, 0.05]) if p["light_on_dark"] else np.array([0.97, 0.97, 0.97])
    ref_rgb = ref.rgb * ref.a[:, :, None] + bg * (1 - ref.a[:, :, None])
    rec = reconstruct(art, p, fw, fh)  # the reference already contains every adjustment
    pass  # bundled import
    size = len(to_ansi(art, "truecolor").encode("utf-8")) if art.has_color() else len(art.to_text().encode("utf-8"))
    return quality_metrics(ref_rgb, rec, size)


# ---------------------------------------------------------------------- Smart Optimize
COMPAT_SCORE = {"ascii": 1.0, "cp437": 0.9, "unicode": 0.8, "braille": 0.7, "sextant": 0.45, "katakana": 0.4, "emoji": 0.3}

OPT_PRESETS = {
    "detail": {"label": "Maximum detail", "w": {"ssim": .45, "edge": .45, "lum": .1},
               "cands": [{"mode": "sextant", "color": "original"}, {"mode": "braille", "dither": "floyd"},
                         {"mode": "braille", "adaptive": True}, {"mode": "dense"}, {"mode": "quadrant", "color": "original"},
                         {"mode": "typographic"}, {"mode": "truecolor"}]},
    "similarity": {"label": "Maximum visual similarity", "w": {"ssim": .35, "lum": .3, "color": .35},
                   "cands": [{"mode": "truecolor"}, {"mode": "dense"}, {"mode": "mosaic"},
                             {"mode": "sextant", "color": "original"}, {"mode": "quadrant", "color": "original"},
                             {"mode": "ansi256"}, {"mode": "multilayer"}]},
    "readability": {"label": "Maximum text readability", "w": {"ssim": .35, "edge": .3, "compat": .35},
                    "cands": [{"mode": "classic"}, {"mode": "classic", "dither": "floyd"}, {"mode": "typographic"},
                              {"mode": "adaptive"}, {"mode": "hybrid"}, {"mode": "extended"}]},
    "small": {"label": "Minimum output size", "w": {"size": .55, "ssim": .45},
              "cands": [{"mode": "classic", "cols": 60}, {"mode": "blocks", "cols": 60}, {"mode": "braille", "cols": 50},
                        {"mode": "mono", "cols": 60}, {"mode": "binary", "cols": 60}, {"mode": "classic", "cols": 80}]},
    "terminal": {"label": "Terminal compatibility", "w": {"ssim": .45, "compat": .4, "color": .15},
                 "cands": [{"mode": "ansi256", "cols": 80}, {"mode": "ansi16", "cols": 80}, {"mode": "half", "cols": 80},
                           {"mode": "classic", "cols": 80}, {"mode": "mono", "cols": 80}, {"mode": "truecolor", "cols": 80}]},
    "portrait": {"label": "Portrait mode", "w": {"ssim": .5, "edge": .3, "lum": .2},
                 "cands": [{"mode": "braille", "dither": "floyd", "local_contrast": 0.6},
                           {"mode": "typographic", "equalize": "clahe"}, {"mode": "adaptive", "local_contrast": 0.5},
                           {"mode": "truecolor"}, {"mode": "classic", "dither": "floyd", "equalize": "clahe"}]},
    "landscape": {"label": "Landscape mode", "w": {"ssim": .35, "color": .4, "lum": .25},
                  "cands": [{"mode": "truecolor", "cols": 160}, {"mode": "sextant", "color": "original", "cols": 160},
                            {"mode": "mosaic", "cols": 140}, {"mode": "ansi256", "cols": 160}, {"mode": "dense", "cols": 140}]},
    "logo": {"label": "Logo mode", "w": {"edge": .5, "ssim": .5},
             "cands": [{"mode": "silhouette"}, {"mode": "quadrant"}, {"mode": "sextant"}, {"mode": "quadrant", "color": "original"},
                       {"mode": "sextant", "color": "original"}, {"mode": "edge"}, {"mode": "contour"}]},
    "braille": {"label": "Braille mode", "w": {"ssim": .6, "edge": .4},
                "cands": [{"mode": "braille", "threshold": t} for t in (0.35, 0.5, 0.65)]
                + [{"mode": "braille", "adaptive": True}, {"mode": "braille", "dither": "floyd"},
                   {"mode": "braille", "dither": "atkinson"}, {"mode": "braille", "dither": "bayer"}]},
}

METRIC_NOTE = ("Scores are automated approximations of visual quality (luminance RMSE, SSIM, edge correlation, "
               "CIELAB colour error, output size and terminal compatibility); they do not replace looking at the result.")


def optimize(src: RasterImage, base: dict, preset: str = "similarity", top: int = 6, cancel=None, progress=None) -> dict:
    """Render the preset's candidates, score them and return the best ones (with metrics)."""
    require_numpy()
    spec = OPT_PRESETS[preset]
    base = sanitize_params(base)
    results = []
    t0 = time.perf_counter()
    cands = spec["cands"]
    for i, ov in enumerate(cands):
        if cancel is not None and cancel():
            raise RenderCancelled()
        p = dict(base)
        p.update({"dither": "none", "adaptive": False, "color": "none"})
        p.update(ov)
        p = sanitize_params(p)
        art, st = render_image_art(src, p)
        q = evaluate(src, art, p)
        results.append({"params": p, "art": art, "stats": st, "metrics": q})
        if progress:
            progress(i + 1, len(cands))
    max_bytes = max(r["metrics"]["bytes"] for r in results) or 1
    w = spec["w"]
    for r in results:
        q = r["metrics"]
        parts = {"ssim": max(0.0, q["ssim"]), "lum": max(0.0, 1 - q["lum_rmse"] * 2), "edge": (q["edge_corr"] + 1) / 2,
                 "color": max(0.0, 1 - q["color_de"] / 50), "size": 1 - q["bytes"] / max_bytes,
                 "compat": COMPAT_SCORE[MODES[r["params"]["mode"]][5]]}
        r["score"] = round(sum(w.get(k, 0) * v for k, v in parts.items()), 4)
        r["parts"] = {k: round(v, 3) for k, v in parts.items() if k in w}
    results.sort(key=lambda r: -r["score"])
    return {"preset": preset, "label": spec["label"], "note": METRIC_NOTE, "ms": round((time.perf_counter() - t0) * 1000),
            "results": results[:top], "evaluated": len(results)}


# ==========================================================================
# module: leerbox/imganim.py
# ==========================================================================
"""Animation-to-Art, typographic compositions, comparison exports and Image Studio projects."""

import base64
import html
import io
import json
import math
import time
import zipfile


MAX_ANIM_FRAMES_OUT = 600


# ---------------------------------------------------------------------- animation conversion
def select_frames(n: int, start: int = 0, end: int = -1, step: int = 1) -> list[int]:
    end = n - 1 if end < 0 or end >= n else end
    start = max(0, min(start, end))
    step = max(1, step)
    return list(range(start, end + 1, step))[:MAX_ANIM_FRAMES_OUT]


def convert_animation(frames: list[RasterImage], durations: list[int], params: dict, start: int = 0, end: int = -1,
                      step: int = 1, fps: float = 0.0, cancel=None, progress=None):
    """Convert selected frames with the Image Studio settings. Returns (arts, durations_ms, stats)."""
    require_numpy()
    idx = select_frames(len(frames), start, end, step)
    p = sanitize_params(params)
    arts, durs = [], []
    t0 = time.perf_counter()
    for k, i in enumerate(idx):
        if cancel is not None and cancel():
            raise RenderCancelled()
        art, _ = render_image_art(frames[i], p)
        arts.append(art)
        if fps > 0:
            durs.append(int(round(1000 / fps)))
        else:  # frame skipping keeps the original timing by summing skipped durations
            durs.append(sum(durations[j] for j in range(i, min(len(frames), i + max(1, step)))))
        if progress:
            progress(k + 1, len(idx))
    return arts, durs, {"frames": len(arts), "ms": round((time.perf_counter() - t0) * 1000), "mode": p["mode"]}


def to_animated_html(arts: list[Art], durs: list[int], s: ExportSettings | None = None, loop: bool = True,
                     title: str = "LeerBox Animation") -> str:
    """Self-contained HTML page with an inline player (no network access, no external files)."""
    s = s or ExportSettings()
    frames = [to_html_fragment(a, s) for a in arts]
    data = json.dumps({"frames": frames, "durations": [max(10, int(d)) for d in durs], "loop": bool(loop)})
    data = data.replace("</", "<\\/").replace("<!--", "<\\!--")
    bg = "transparent" if s.transparent else html.escape(s.background)
    return ("<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">"
            "<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; script-src 'unsafe-inline'; "
            "style-src 'unsafe-inline'\">"
            f"<title>{html.escape(title)}</title><style>body{{margin:0;background:{bg};color:#ccc;font:13px system-ui}}"
            "#bar{position:fixed;bottom:8px;right:8px;opacity:.8}button{font:inherit}</style></head><body>"
            "<div id=\"stage\"></div><div id=\"bar\"><button id=\"pp\">Pause</button> <span id=\"fi\"></span></div>"
            f"<script>var D={data};var i=0,playing=true,t=null,st=document.getElementById('stage'),fi=document.getElementById('fi');"
            "function show(){st.innerHTML=D.frames[i];fi.textContent=(i+1)+'/'+D.frames.length;}"
            "function step(){show();t=setTimeout(function(){i++;if(i>=D.frames.length){if(!D.loop){i=D.frames.length-1;return;}i=0;}"
            "if(playing)step();},D.durations[i]);}"
            "document.getElementById('pp').onclick=function(){playing=!playing;this.textContent=playing?'Pause':'Play';"
            "if(playing){clearTimeout(t);step();}};step();</script></body></html>\n")


def to_gif(arts: list[Art], durs: list[int], s: ExportSettings | None = None, loop: bool = True) -> bytes:
    """Animated GIF of the rendered text art (Pillow)."""
    from PIL import Image
    s = s or ExportSettings()
    imgs = [render_image(a, s) for a in arts]
    W = max(i.width for i in imgs); H = max(i.height for i in imgs)
    bg = split_rgb(hex_to_rgb(s.background))
    out = []
    for im in imgs:
        base = Image.new("RGBA", (W, H), (*bg, 255))
        base.alpha_composite(im)
        out.append(base.convert("RGB").quantize(colors=255, method=Image.Quantize.MEDIANCUT, dither=Image.Dither.NONE))
    buf = io.BytesIO()
    out[0].save(buf, "GIF", save_all=True, append_images=out[1:], duration=[max(20, int(d)) for d in durs],
                loop=0 if loop else 1, disposal=1, optimize=False)
    return buf.getvalue()


def to_frame_zip(arts: list[Art], fmt: str = "txt", s: ExportSettings | None = None, durs: list[int] | None = None) -> bytes:
    """ZIP with one file per frame (txt, ans or png) plus a JSON timing manifest."""
    pass  # bundled import
    s = s or ExportSettings()
    buf = io.BytesIO()
    ext = {"txt": "txt", "ansi": "ans", "png": "png", "svg": "svg", "html": "html"}[fmt]
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for i, a in enumerate(arts):
            z.writestr(f"frame_{i + 1:04d}.{ext}", export_bytes(a, fmt, s))
        z.writestr("frames.json", json.dumps({"frames": len(arts), "durations_ms": list(durs or [100] * len(arts)),
                                             "format": ext}, indent=1))
    return buf.getvalue()


def to_ansi_script(arts: list[Art], durs: list[int], shell: str = "bash", mode: str = "truecolor", loop: bool = True) -> str:
    """Terminal player script. Frames contain only SGR colour codes (sanitised); the script adds cursor-home."""
    frames = [to_ansi(a, mode) for a in arts]
    if shell == "powershell":
        lines = ["# LeerBox ANSI animation (PowerShell 7+). Ctrl+C to stop.", "$e = [char]27", "$frames = @("]
        for f in frames:
            body = f.replace("'", "''").replace("\x1b", "' + $e + '")
            lines.append(f"  ('{body}'),")
        lines[-1] = lines[-1].rstrip(",")
        lines += [")", f"$delays = @({', '.join(str(max(10, int(d))) for d in durs)})",
                  "[Console]::Write(\"$e[2J$e[?25l\")", "try {", "  do {",
                  "    for ($i = 0; $i -lt $frames.Count; $i++) {",
                  "      [Console]::Write(\"$e[H\" + $frames[$i]); Start-Sleep -Milliseconds $delays[$i]", "    }",
                  f"  }} while (${'true' if loop else 'false'})", "} finally { [Console]::Write(\"$e[0m$e[?25h\") }", ""]
        return "\n".join(lines)
    out = ["#!/usr/bin/env bash", "# LeerBox ANSI animation. Ctrl+C to stop.", "frames=()"]
    for f in frames:
        out.append("frames+=(" + "$'" + f.replace("\\", "\\\\").replace("'", "\\'").replace("\x1b", "\\e")
                   .replace("\n", "\\n") + "')")
    out.append("delays=(" + " ".join(f"{max(10, int(d)) / 1000:.3f}" for d in durs) + ")")
    body = ["for i in \"${!frames[@]}\"; do", "  printf '\\e[H%s' \"${frames[$i]}\"", "  sleep \"${delays[$i]}\"", "done"]
    out += ["trap 'printf \"\\e[0m\\e[?25h\\n\"; exit' INT TERM", "printf '\\e[2J\\e[?25l'"]
    out += (["while :; do"] + ["  " + b for b in body] + ["done"]) if loop else body
    out += ["printf '\\e[0m\\e[?25h\\n'", ""]
    return "\n".join(out)


# ---------------------------------------------------------------------- typographic composition (graphical)
def compose_typographic(src: RasterImage, params: dict, font_size: float = 12.0, vary: str = "opacity",
                        rotate: int = 0, max_side: int = 2400) -> dict:
    """Graphical composition: the phrase is set as lines of real text whose colour, opacity, size or weight
    follow the image. This is a *graphic* (PNG/SVG), not monospaced text art."""
    require_numpy()
    pass  # bundled import
    pass  # bundled import
    p = sanitize_params(params)
    fs = max(4.0, min(64.0, float(font_size)))
    cw, lh = fs * 0.6021, fs * 1.15
    img = src
    if rotate == 90:
        pass  # bundled import
        img = rotate90(src, 270)
    scale = min(1.0, max_side / max(img.width, img.height))
    W, H = img.width * scale, img.height * scale
    cols, rows = max(4, int(W / cw)), max(2, int(H / lh))
    smp = resample_area(img, cols, rows)
    rgb = composite(smp, 0xFFFFFF if not p["light_on_dark"] else 0x000000)
    L = luminance(rgb)
    stream, rtl = _text_stream(p["text"], p["text_dir"])
    runs, k = [], 0
    for y in range(rows):
        xs = range(cols - 1, -1, -1) if rtl else range(cols)
        for x in xs:
            if p["transparent_bg"] and smp.a[y, x] < 0.5:
                continue
            g, w = stream[k % len(stream)]
            k += 1
            if not g.strip():
                continue
            v = float(L[y, x])
            ink = v if p["light_on_dark"] else 1 - v
            r8 = [int(round(c * 255)) for c in rgb[y, x]]
            color = "#%02x%02x%02x" % tuple(r8) if p["color"] != "none" else ("#ffffff" if p["light_on_dark"] else "#000000")
            run = {"x": round(x * cw, 2), "y": round(y * lh + fs, 2), "ch": g, "color": color, "alpha": 1.0,
                   "size": fs, "bold": False}
            if vary == "opacity":
                run["alpha"] = round(max(0.06, ink), 3)
            elif vary == "size":
                run["size"] = round(fs * (0.35 + 0.9 * ink), 2)
            elif vary == "weight":
                run["bold"] = ink > 0.5
                run["alpha"] = round(max(0.15, ink), 3)
            runs.append(run)
    return {"kind": "typographic-composition", "width": round(cols * cw, 2), "height": round(rows * lh, 2),
            "background": "#000000" if p["light_on_dark"] else "#ffffff", "font_size": fs, "rotate": rotate,
            "rtl": rtl, "runs": runs}


def composition_svg(comp: dict) -> str:
    W, H = comp["width"], comp["height"]
    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}">',
           f'<rect width="100%" height="100%" fill="{comp["background"]}"/>',
           '<g font-family="DejaVu Sans Mono, Consolas, monospace">']
    for r in comp["runs"]:
        out.append(f'<text x="{r["x"]}" y="{r["y"]}" font-size="{r["size"]}" fill="{r["color"]}"'
                   + (f' fill-opacity="{r["alpha"]}"' if r["alpha"] < 1 else "")
                   + (' font-weight="bold"' if r["bold"] else "") + f'>{html.escape(r["ch"], quote=False)}</text>')
    out.append("</g></svg>\n")
    svg = "".join(out)
    if comp.get("rotate") == 90:
        svg = svg.replace('<g font-family', f'<g transform="rotate(90 {W / 2} {H / 2})" font-family', 1)
    return svg


def composition_png(comp: dict, scale: float = 1.0) -> bytes:
    from PIL import Image, ImageDraw, ImageFont
    import zlib
    pass  # bundled import
    W, H = int(comp["width"] * scale + 0.5), int(comp["height"] * scale + 0.5)
    img = Image.new("RGBA", (W, H), (*split_rgb(hex_to_rgb(comp["background"])), 255))
    layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    d = ImageDraw.Draw(layer)
    data = zlib.decompress(load_resource("DejaVuSans.ttf.z"))
    fonts = {}
    for r in comp["runs"]:
        sz = max(3, int(r["size"] * scale + 0.5))
        f = fonts.get(sz)
        if f is None:
            f = fonts[sz] = ImageFont.truetype(io.BytesIO(data), sz)
        col = split_rgb(hex_to_rgb(r["color"]))
        a = int(255 * r["alpha"])
        pos = (r["x"] * scale, r["y"] * scale)
        d.text(pos, r["ch"], font=f, fill=(*col, a), anchor="ls",
               stroke_width=1 if r["bold"] else 0, stroke_fill=(*col, a))
    img.alpha_composite(layer)
    if comp.get("rotate") == 90:
        img = img.rotate(-90, expand=True)
    buf = io.BytesIO()
    img.save(buf, "PNG")
    return buf.getvalue()


# ---------------------------------------------------------------------- comparison export
def comparison_png(src: RasterImage, art: Art, s: ExportSettings | None = None, layout: str = "side") -> bytes:
    """Original image and the rendered text art side by side (or stacked)."""
    from PIL import Image
    s = s or ExportSettings()
    art_img = render_image(art, s)
    h = art_img.height
    w = max(1, int(src.width * h / src.height + 0.5))
    if layout == "stack":
        w = art_img.width
        h = max(1, int(src.height * w / src.width + 0.5))
    rgba = Image.frombytes("RGBA", (src.width, src.height), src.to_rgba_bytes()).resize((w, h), Image.Resampling.LANCZOS)
    bg = (*split_rgb(hex_to_rgb(s.background)), 255)
    gap = max(8, int(16 * s.scale))
    if layout == "stack":
        out = Image.new("RGBA", (art_img.width, h + gap + art_img.height), bg)
        out.alpha_composite(rgba, (0, 0)); out.alpha_composite(art_img, (0, h + gap))
    else:
        out = Image.new("RGBA", (w + gap + art_img.width, max(h, art_img.height)), bg)
        out.alpha_composite(rgba, (0, 0)); out.alpha_composite(art_img, (w + gap, 0))
    buf = io.BytesIO()
    out.save(buf, "PNG")
    return buf.getvalue()


# ---------------------------------------------------------------------- Image Studio projects
MAX_PROJECT_IMAGE = 25 * 1024 * 1024


def make_image_project(params: dict, image_bytes: bytes | None, image_name: str = "", effects: list | None = None,
                       export: dict | None = None, workspace: str = "image") -> str:
    if image_bytes is not None and len(image_bytes) > MAX_PROJECT_IMAGE:
        image_bytes = None  # too large to embed; the project then stores settings only
    d = {"format": "leerbox-image-project", "version": 1, "workspace": workspace,
         "params": sanitize_params(params), "effects": effects or [], "export": export or {},
         "image": ({"name": image_name[:200], "data": base64.b64encode(image_bytes).decode("ascii")}
                   if image_bytes is not None else None)}
    return json.dumps(d, ensure_ascii=False)


def parse_image_project(text: str | bytes) -> dict:
    pass  # bundled import
    if isinstance(text, bytes):
        if len(text) > 40 * 1024 * 1024:
            raise ProjectError("project file too large")
        text = text.decode("utf-8", "replace")
    try:
        d = json.loads(text)
    except ValueError as exc:
        raise ProjectError(f"invalid project: {exc}") from exc
    if not isinstance(d, dict) or d.get("format") != "leerbox-image-project":
        raise ProjectError("not a LeerBox image project")
    out = {"workspace": d.get("workspace") if d.get("workspace") in ("image", "animation") else "image",
           "params": sanitize_params(d.get("params") if isinstance(d.get("params"), dict) else {}),
           "effects": sanitize_effects(d.get("effects", [])),
           "export": d.get("export") if isinstance(d.get("export"), dict) else {}, "image": None, "image_name": ""}
    im = d.get("image")
    if isinstance(im, dict) and isinstance(im.get("data"), str):
        try:
            raw = base64.b64decode(im["data"], validate=True)
        except ValueError as exc:
            raise ProjectError("embedded image is not valid base64") from exc
        if len(raw) > MAX_PROJECT_IMAGE:
            raise ProjectError("embedded image too large")
        out["image"] = raw
        out["image_name"] = str(im.get("name", ""))[:200]
    return out


# ---------------------------------------------------------------------- batch
def batch_convert(items: list[tuple[str, bytes]], params: dict, fmt: str, s: ExportSettings | None = None,
                  cancel=None, progress=None) -> tuple[bytes, list[dict]]:
    """Convert several images with the same settings into one ZIP. Returns (zip bytes, per-file report)."""
    pass  # bundled import
    s = s or ExportSettings()
    buf = io.BytesIO()
    report = []
    ext = FORMATS[fmt][1]
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for i, (name, data) in enumerate(items):
            if cancel is not None and cancel():
                raise RenderCancelled()
            base = (name.rsplit("/", 1)[-1].rsplit("\\", 1)[-1].rsplit(".", 1)[0] or f"image{i + 1}")[:80]
            try:
                img = decode_image(data, name)
                art, st = render_image_art(img, params)
                z.writestr(f"{i + 1:03d}_{base}{ext}", export_bytes(art, fmt, s))
                report.append({"name": name, "ok": True, "cols": st["cols"], "rows": st["rows"], "ms": st["ms"]})
            except Exception as exc:  # report and continue with the next file
                report.append({"name": name, "ok": False, "error": str(exc)})
            if progress:
                progress(i + 1, len(items))
        z.writestr("batch_report.json", json.dumps(report, indent=1))
    return buf.getvalue(), report


# ==========================================================================
# module: leerbox/smart.py
# ==========================================================================
"""Deterministic local "smart" features (no cloud, no randomness unless seeded).

How recommendations are produced
--------------------------------
1. Every candidate font renders the current text (cached by the engine).
2. Fonts that cannot draw every character (after Unicode fallbacks) are dropped.
3. The rendered size (columns × rows) is scored against the chosen target:

   =========  ===============  ==============================================
   target     ideal size       score
   =========  ===============  ==============================================
   terminal   ≤ 80 cols        100 − 3·|h − 6| ; −200 if wider than 80 cols
   wide       ≤ 120 cols       100 − 2·|h − 8| ; −200 if wider than 120 cols
   compact    ≤ 60 cols, h ≤ 4 100 − 25·max(0, h − 3) − 0.5·w
   banner     ≤ 160 cols       60 + 4·min(h, 12) ; −200 if wider than 160 cols
   =========  ===============  ==============================================

   Text length adjusts the target: inputs longer than 24 characters receive a
   bonus for compact heights (≤ 5 rows), inputs of 8 characters or fewer a
   bonus for tall fonts (≥ 8 rows).
4. Ties are broken by font name, so results are reproducible.
"""


TARGETS = {"terminal": 80, "wide": 120, "compact": 60, "banner": 160}

CURATED = [
    ("Neon nights", "fig:ansi_shadow", [{"type": "gradient", "mode": "horizontal", "stops": ["#00e5ff", "#b14cff", "#ff3ea5"]}, {"type": "glow", "color": "#b14cff", "radius": 8}]),
    ("Retro terminal", "fig:big", [{"type": "color", "fg": "#33ff66"}, {"type": "frame", "style": "terminal", "title": "tty1"}, {"type": "glow", "color": "#33ff66", "radius": 5}]),
    ("Sunset slant", "fig:slant", [{"type": "gradient", "mode": "vertical", "stops": ["#ffcf5c", "#ff7a59", "#e04e8a"]}]),
    ("Matrix rain", "fig:banner3", [{"type": "matrix", "density": 0.6}]),
    ("Blueprint", "fig:doom", [{"type": "outline", "char": "·", "color": "#4f7dd1"}, {"type": "color", "fg": "#cfe3ff"}, {"type": "frame", "style": "single", "color": "#4f7dd1"}]),
    ("Gold 3D", "fig:colossal", [{"type": "extrude", "depth": 2, "direction": "se", "char": "▒", "color": "#7a5a12"}, {"type": "gradient", "mode": "vertical", "stops": ["#fff1a8", "#e0a526"]}]),
    ("Vaporwave", "fig:ansi_regular", [{"type": "double_shadow"}, {"type": "rainbow", "mode": "diagonal", "saturation": 0.6, "lightness": 0.7}]),
    ("Gothic manuscript", "fig:gothic", [{"type": "color", "fg": "#d8c7a0"}, {"type": "frame", "style": "double", "color": "#8a6d3b"}]),
    ("Cyber glitch", "fig:electronic", [{"type": "glitch", "amount": 0.3, "shift": 2}, {"type": "gradient", "mode": "horizontal", "stops": ["#00ffd5", "#ff2bd6"]}]),
    ("Bloody horror", "fig:bloody", [{"type": "gradient", "mode": "vertical", "stops": ["#ff4d4d", "#6e0000"]}]),
    ("Isometric ice", "fig:isometric1", [{"type": "gradient", "mode": "diagonal", "stops": ["#e0fbff", "#5ac8fa", "#2f6fed"]}]),
    ("Minimal box", "fig:small", [{"type": "frame", "style": "rounded", "padding": 1}]),
    ("Pixel block", "tlf:pagga", [{"type": "rainbow", "mode": "horizontal", "lightness": 0.6}]),
    ("Shadow pop", "fig:standard", [{"type": "shadow", "dx": 1, "dy": 1, "char": "░", "color": "#4c566a"}, {"type": "color", "fg": "#ffd166"}]),
]


def curated_designs(fonts) -> list[dict]:
    out = []
    for name, fid, effects in CURATED:
        if fid not in fonts.entries:
            fid = "fig:standard"
        out.append({"name": name, "font": fid, "effects": [new_effect(e["type"], **{k: v for k, v in e.items() if k != "type"}) for e in effects]})
    return out


RANDOM_EFFECTS = [
    ("gradient", lambda r: {"mode": ["horizontal", "vertical", "diagonal"][r.int(3)],
                            "stops": [_rand_color(r), _rand_color(r), _rand_color(r)][: 2 + r.int(2)]}),
    ("rainbow", lambda r: {"mode": ["horizontal", "vertical", "diagonal"][r.int(3)], "offset": round(r.next(), 2)}),
    ("shadow", lambda r: {"char": "░▒.:"[r.int(4)]}),
    ("frame", lambda r: {"style": ["rounded", "double", "single", "heavy", "ascii"][r.int(5)]}),
    ("outline", lambda r: {"char": "·.:+"[r.int(4)]}),
    ("extrude", lambda r: {"depth": 1 + r.int(3), "direction": ["se", "sw", "ne", "nw"][r.int(4)]}),
]


def _rand_color(r: Rng) -> str:
    pass  # bundled import
    return f"#{hsl(r.next(), 0.55 + 0.4 * r.next(), 0.5 + 0.2 * r.next()):06x}"


def random_design(fonts, seed: int, pool: list[str] | None = None) -> dict:
    r = Rng(seed)
    ids = pool or [fid for fid, e in fonts.entries.items() if e.type in ("figlet", "toilet")]
    fid = ids[r.int(len(ids))] if ids else "fig:standard"
    effects = []
    color_done = False
    for _ in range(1 + r.int(3)):
        kind, gen = RANDOM_EFFECTS[r.int(len(RANDOM_EFFECTS))]
        if kind in ("gradient", "rainbow"):
            if color_done:
                continue
            color_done = True
        if any(e["type"] == kind for e in effects):
            continue
        effects.append(new_effect(kind, **gen(r)))
    # colour effects last so they also tint shadows/frames
    effects.sort(key=lambda e: e["type"] in ("gradient", "rainbow"))
    return {"font": fid, "effects": effects, "seed": seed}


def score(w: int, h: int, target: str, text_len: int) -> float:
    if w == 0 or h == 0:
        return -1000
    if target == "terminal":
        s = 100 - 3 * abs(h - 6) - (200 if w > 80 else 0)
    elif target == "wide":
        s = 100 - 2 * abs(h - 8) - (200 if w > 120 else 0)
    elif target == "compact":
        s = 100 - 25 * max(0, h - 3) - 0.5 * w - (200 if w > 60 else 0)
    else:  # banner
        s = 60 + 4 * min(h, 12) - (200 if w > 160 else 0)
    if text_len > 24 and h <= 5:
        s += 15
    if text_len <= 8 and h >= 8:
        s += 15
    return s


def recommend(engine, text: str, target: str = "terminal", candidates: list[str] | None = None,
              limit: int = 12, cancel=None) -> list[dict]:
    pass  # bundled import
    fonts = engine.fonts
    ids = candidates or [fid for fid, e in fonts.entries.items() if e.type in ("figlet", "toilet")]
    text = text.strip() or "LeerBox"
    out = []
    o = TextOptions()
    for fid in ids:
        if cancel and cancel():
            break
        try:
            if engine.unsupported_chars(fid, text):
                continue
            art = engine.render(fid, text, o)
        except Exception:  # noqa: BLE001 - a broken font must not stop recommendations
            continue
        w, h = art.width, art.height
        out.append({"id": fid, "width": w, "height": h, "score": score(w, h, target, len(text))})
    out.sort(key=lambda r: (-r["score"], fonts.entries[r["id"]].name.lower()))
    return out[:limit]


def compatible_fonts(engine, text: str, ids: list[str]) -> list[str]:
    return [fid for fid in ids if not engine.unsupported_chars(fid, text)]


def preview_scale(art_w: int, art_h: int, avail_w: int, avail_h: int, cell_w: float = 8.4, cell_h: float = 17.0) -> float:
    """Largest zoom (≤ 1.6) that fits the art into the available preview area."""
    if art_w <= 0 or art_h <= 0:
        return 1.0
    z = min(avail_w / (art_w * cell_w), avail_h / (art_h * cell_h), 1.6)
    return max(0.25, round(z, 2))


def width_warning(art_w: int) -> str | None:
    if art_w > 200:
        return f"Output is {art_w} columns wide — it will wrap in most terminals. Try a compact font or a wrap width."
    if art_w > 120:
        return f"Output is {art_w} columns — wider than a 120-column terminal."
    if art_w > 80:
        return f"Output is {art_w} columns — wider than a standard 80-column terminal."
    return None


# ==========================================================================
# module: leerbox/cli.py
# ==========================================================================
"""Command-line interface (headless rendering and export).

Examples
  python LeerBox_Text_Art_Studio_V3.py                       # start the GUI
  python LeerBox_Text_Art_Studio_V3.py --text "Hello" --font slant
  python LeerBox_Text_Art_Studio_V3.py --text "Hi" --font big --effect gradient --format png -o hi.png
  python LeerBox_Text_Art_Studio_V3.py --list-fonts --search 3d
  python LeerBox_Text_Art_Studio_V3.py --style fraktur --text "Gothic"
  python LeerBox_Text_Art_Studio_V3.py --image photo.jpg --image-mode braille --cols 120
  python LeerBox_Text_Art_Studio_V3.py --image logo.png --set color=original --set mode=sextant --format png -o out.png
  python LeerBox_Text_Art_Studio_V3.py --image photo.jpg --analyze
  python LeerBox_Text_Art_Studio_V3.py --image photo.jpg --optimize portrait
  python LeerBox_Text_Art_Studio_V3.py --image anim.gif --animate html -o anim.html
"""

import argparse
import json
import sys

CLI_FX_DEFAULTS = DEFAULTS


def resolve_font(fm: FontManager, name: str) -> str:
    if name in fm.entries:
        return name
    for prefix in ("fig:", "tlf:", "ras:", ""):
        if prefix + name in fm.entries:
            return prefix + name
    low = name.lower()
    for fid, e in fm.entries.items():
        if e.name.lower() == low:
            return fid
    hits = fm.search(name)
    if hits:
        return hits[0]
    raise SystemExit(f"font not found: {name}")


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="leerbox", description="LeerBox Text Art Studio 3.0 — headless mode")
    p.add_argument("--text", "-t", help="text to render (use '-' to read stdin)")
    p.add_argument("--font", "-f", default="standard")
    p.add_argument("--list-fonts", action="store_true")
    p.add_argument("--search", default="")
    p.add_argument("--format", default="txt", choices=sorted(FORMATS))
    p.add_argument("--output", "-o", help="output file (default: stdout for text formats)")
    p.add_argument("--effect", action="append", default=[], help=f"effect name ({', '.join(CLI_FX_DEFAULTS)}) or JSON object")
    p.add_argument("--layout", default="default", choices=["default", "full", "fitted", "smush", "universal"])
    p.add_argument("--width", type=int, default=0)
    p.add_argument("--align", default="left", choices=["left", "center", "right"])
    p.add_argument("--raster-mode", default="block")
    p.add_argument("--style", choices=sorted(STYLE_NAMES), help="apply a Unicode style instead of a font")
    p.add_argument("--encode", choices=sorted(ENCODINGS))
    p.add_argument("--ansi", default="truecolor", choices=["truecolor", "256", "16", "none"])
    p.add_argument("--scale", type=float, default=1.0)
    g = p.add_argument_group("Image Studio (needs NumPy; Pillow for most formats)")
    g.add_argument("--image", help="image file to convert to text art")
    g.add_argument("--image-mode", help="conversion mode (see --list-image-modes)")
    g.add_argument("--cols", type=int, help="output width in characters")
    g.add_argument("--set", action="append", default=[], metavar="KEY=VALUE", help="any Image Studio parameter")
    g.add_argument("--analyze", action="store_true", help="print the image analysis and recommendations as JSON")
    g.add_argument("--optimize", metavar="PRESET", help="Smart Optimize preset (detail, similarity, readability, small, "
                                                       "terminal, portrait, landscape, logo, braille)")
    g.add_argument("--animate", choices=["html", "gif", "zip", "sh", "ps1"], help="convert every frame of an animation")
    g.add_argument("--list-image-modes", action="store_true")
    g.add_argument("--formats", action="store_true", help="show which image formats can be decoded here")
    return p


def run_image_cli(a) -> int:
    pass  # bundled import
    pass  # bundled import
    if a.list_image_modes:
        for k, m in MODES.items():
            print(f"{k}	{m[0]}	{m[6]}")
        return 0
    if a.formats:
        print(json.dumps(decoder_capabilities(), indent=1))
        return 0
    params = {}
    for kv in a.set:
        k, _, v = kv.partition("=")
        if k not in IMG_PARAMS:
            raise SystemExit(f"unknown image parameter: {k}")
        params[k] = v
    if a.image_mode:
        params["mode"] = a.image_mode
    if a.cols:
        params["cols"] = a.cols
    with open(a.image, "rb") as fh:
        data = fh.read()
    s = ExportSettings(ansi_mode=a.ansi, scale=a.scale)
    out = None
    if a.animate:
        pass  # bundled import
        frames, durs, _ = decode_frames(data)
        arts, d2, _ = convert_animation(frames, durs, params)
        out = {"html": lambda: to_animated_html(arts, d2, s).encode("utf-8"), "gif": lambda: to_gif(arts, d2, s),
               "zip": lambda: to_frame_zip(arts, "txt", s, d2),
               "sh": lambda: to_ansi_script(arts, d2, "bash", a.ansi).encode("utf-8"),
               "ps1": lambda: to_ansi_script(arts, d2, "powershell", a.ansi).encode("utf-8")}[a.animate]()
    else:
        img = decode_image(data, a.image)
        if a.analyze:
            pass  # bundled import
            print(json.dumps(analyze(img), indent=1, ensure_ascii=False))
            return 0
        if a.optimize:
            pass  # bundled import
            if a.optimize not in OPT_PRESETS:
                raise SystemExit(f"unknown preset; choose from {', '.join(OPT_PRESETS)}")
            res = optimize(img, params, a.optimize)
            print(res["note"])
            for r in res["results"]:
                print(f"{r['score']:.3f}  {r['params']['mode']:<12} {r['metrics']}")
            return 0
        art, _ = render_image_art(img, params)
        out = export_bytes(art, a.format, s)
    if a.output:
        with open(a.output, "wb") as fh:
            fh.write(out)
        if sys.stderr is not None:
            print(f"wrote {a.output} ({len(out)} bytes)", file=sys.stderr)
        return 0
    if sys.stdout is None:
        raise SystemExit("no console available: use --output FILE")
    if a.format in ("png", "jpeg", "webp", "bmp") or a.animate in ("gif", "zip"):
        raise SystemExit("binary formats need --output")
    sys.stdout.write(out.decode("utf-8"))
    return 0


def run_cli(argv: list[str]) -> int:
    a = build_parser().parse_args(argv)
    if sys.stdout is not None and hasattr(sys.stdout, "reconfigure"):
        try:
            sys.stdout.reconfigure(encoding="utf-8")
        except (OSError, ValueError):
            pass
    if a.image or a.list_image_modes or a.formats:
        return run_image_cli(a)
    if a.list_fonts:
        fm = FontManager()
        for fid in fm.search(a.search):
            e = fm.entries[fid]
            print(f"{fid}\t{e.category}\th{e.height}\t{e.meta.get('licenseTier')}")
        return 0
    text = sys.stdin.read() if a.text == "-" else (a.text if a.text is not None else "LeerBox")
    if a.style:
        print(stylize(text, a.style))
        return 0
    if a.encode:
        print(encode(text, a.encode))
        return 0
    fm = FontManager()
    eng = RenderingEngine(fm)
    fid = resolve_font(fm, a.font)
    effects = []
    for spec in a.effect:
        if spec.strip().startswith("{"):
            obj = json.loads(spec)
            effects.append(new_effect(obj.pop("type"), **obj))
        else:
            effects.append(new_effect(spec))
    o = TextOptions(h_layout=a.layout, width=a.width, align=a.align, raster_mode=a.raster_mode)
    art = eng.render(fid, text, o, effects)
    data = export_bytes(art, a.format, ExportSettings(ansi_mode=a.ansi, scale=a.scale))
    if a.output:
        with open(a.output, "wb") as fh:
            fh.write(data)
        if sys.stderr is not None:  # windowed EXE builds have no console streams
            print(f"wrote {a.output} ({len(data)} bytes)", file=sys.stderr)
    else:
        if sys.stdout is None:
            raise SystemExit("no console available: use --output FILE")
        if a.format in ("png", "jpeg", "webp", "bmp"):
            raise SystemExit("binary formats need --output")
        sys.stdout.write(data.decode("utf-8"))
    return 0


def entry() -> None:
    if len(sys.argv) > 1:
        raise SystemExit(run_cli(sys.argv[1:]))
    gui_main = main  # bundled import
    gui_main()


# ==========================================================================
# module: leerbox/ui/image_ws.py
# ==========================================================================
"""Image-to-Art and Animation-to-Art workspaces for the Tk desktop edition.

Both workspaces share the application's export engine, settings manager (presets, favourite palettes),
colour/effects engines and project format. Rendering runs on a "latest job only" worker thread.
"""

import io
import os
import queue
import threading
import time
import tkinter as tk
from tkinter import filedialog, messagebox, simpledialog, ttk


COL_PRESETS = ["40", "80", "120", "200", "300", "500", "1000"]
ADJUST_KEYS = ["exposure", "brightness", "contrast", "gamma", "saturation", "vibrance", "hue", "sharpness", "blur",
               "denoise", "black", "white", "highlights", "shadows", "posterize", "local_contrast", "remove_bg"]
LABELS = {
    "cols": "Width (chars)", "rows": "Height (0 = auto)", "cell_aspect": "Cell aspect w/h", "lock_aspect": "Lock aspect",
    "target_aspect": "Custom aspect (0 = image)", "fit": "Fit", "crop_x0": "Crop left", "crop_y0": "Crop top",
    "crop_x1": "Crop right", "crop_y1": "Crop bottom", "rotate": "Rotate 90°", "angle": "Rotate (free °)",
    "flip_h": "Flip horizontal", "flip_v": "Flip vertical", "pad": "Padding", "remove_bg": "Remove background",
    "local_contrast": "Local contrast", "equalize": "Histogram equalization", "palette_reverse": "Reverse density",
    "dither_strength": "Dither strength", "threshold": "Threshold / dot sensitivity", "adaptive": "Adaptive threshold",
    "edge_method": "Edge method", "edge_strength": "Edge strength", "edge_threshold": "Edge threshold",
    "levels": "Contour levels", "luma": "Luminance", "light_on_dark": "Light text on dark", "color": "Colour mode",
    "colors": "Custom colours", "gradient": "Gradient stops", "dominant_k": "Dominant colours",
    "color_target": "Colour target", "background": "Background", "transparent_bg": "Keep transparency empty",
    "text": "Text / words", "text_mode": "Word layout", "text_dir": "Direction", "seed": "Random seed",
}
SECTIONS = [
    ("ALGORITHM", ["luma", "dither", "dither_strength", "threshold", "adaptive", "light_on_dark", "seed"]),
    ("CUSTOM WORDS", ["text", "text_mode", "text_dir"]),
    ("OUTPUT RESOLUTION", ["cols", "rows", "cell_aspect", "lock_aspect", "target_aspect", "fit"]),
    ("GEOMETRY", ["crop_x0", "crop_y0", "crop_x1", "crop_y1", "rotate", "angle", "flip_h", "flip_v", "pad"]),
    ("IMAGE ADJUSTMENTS", ADJUST_KEYS + ["equalize", "grayscale", "invert"]),
    ("EDGES", ["edge_method", "edge_strength", "edge_threshold", "levels"]),
    ("COLOURS & BACKGROUND", ["color", "colors", "gradient", "dominant_k", "color_target", "background", "transparent_bg"]),
]


def _fmt_bytes(n: float) -> str:
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024
    return f"{n:.1f} GB"


class _Worker(threading.Thread):
    """Latest-job-only background worker with a cancellation flag for the running job."""

    def __init__(self, results: queue.Queue):
        super().__init__(daemon=True)
        self.results, self.cv, self.job, self.cancel_gen = results, threading.Condition(), None, -1

    def submit(self, tag, gen, fn):
        with self.cv:
            self.job = (tag, gen, fn)
            self.cv.notify()

    def run(self):
        while True:
            with self.cv:
                while self.job is None:
                    self.cv.wait()
                (tag, gen, fn), self.job = self.job, None
            t0 = time.perf_counter()
            try:
                res, err = fn(), None
            except Exception as exc:  # noqa: BLE001 - shown in the UI
                res, err = None, exc
            self.results.put((tag, gen, res, err, time.perf_counter() - t0))


class _Base(ttk.Frame):
    """Shared plumbing: param variables, canvas preview with zoom/pan, status line."""

    def __init__(self, parent, app, colors):
        super().__init__(parent, style="Bg0.TFrame")
        self.app, self.C = app, colors
        self.results: queue.Queue = queue.Queue()
        self.worker = _Worker(self.results)
        self.worker.start()
        self.gen = 0
        self.zoom = 1.0
        self.photo = None
        self.after(60, self._poll)

    def _scroll(self, parent):
        cv = tk.Canvas(parent, bg=self.C["bg1"], highlightthickness=0, width=330)
        sb = ttk.Scrollbar(parent, command=cv.yview)
        inner = ttk.Frame(cv, padding=(8, 4))
        inner.bind("<Configure>", lambda e: cv.configure(scrollregion=cv.bbox("all")))
        win = cv.create_window(0, 0, window=inner, anchor="nw")
        cv.bind("<Configure>", lambda e: cv.itemconfigure(win, width=e.width))
        cv.configure(yscrollcommand=sb.set)
        cv.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")
        inner.bind("<Enter>", lambda e: cv.bind_all("<MouseWheel>", lambda ev: cv.yview_scroll(int(-ev.delta / 60), "units")))
        inner.bind("<Leave>", lambda e: cv.unbind_all("<MouseWheel>"))
        return inner

    def _head(self, parent, text):
        ttk.Label(parent, text=text, style="Head.TLabel").pack(anchor="w", pady=(10, 3))

    def fix_sash(self):
        p = getattr(self, "_paned", None)
        if p is None:
            return
        self.update_idletasks()
        w = self.winfo_width()
        if w < 200:
            self.after(80, self.fix_sash)
            return
        try:
            p.sashpos(0, 300)
            p.sashpos(1, max(600, w - 370))
        except tk.TclError:
            pass

    def _poll(self):
        try:
            while True:
                tag, gen, res, err, dt = self.results.get_nowait()
                self.on_result(tag, gen, res, err, dt)
        except queue.Empty:
            pass
        self.after(50, self._poll)

    def on_result(self, tag, gen, res, err, dt):  # overridden
        pass

    def export_settings(self) -> ExportSettings:
        return self.app._read_export_settings()

    def ask_save(self, title, ext, data: bytes):
        path = filedialog.asksaveasfilename(parent=self, title=title, defaultextension=ext,
                                            filetypes=[(ext.upper().strip("."), "*" + ext), ("All files", "*.*")])
        if path:
            atomic_write(path, data)
            self.set_status(f"Saved {os.path.basename(path)} ({_fmt_bytes(len(data))})")

    def set_status(self, msg):
        self.status_var.set(msg)


