        ttk.Label(b, text=f"{APP_VERSION} {APP_EDITION}  ·  offline  ·  {self.fonts.stats()['genuine']} genuine FIGlet/TOIlet fonts",
                  style="Sub.TLabel").pack(anchor="w")
