        self.view_buttons = {}
        for key, label in (("preview", "Preview"), ("gallery", "All-font gallery"), ("compare", "Compare")):
            bt = ttk.Button(tb, text=label, style="Tab.TButton", command=lambda k=key: self.set_view(k))
            bt.pack(side="left", padx=1)
