        self.evars["embed_font"] = v
        ttk.Checkbutton(f, text="Embed DejaVu Sans Mono in HTML/SVG", variable=v).grid(row=8, column=0, columnspan=2, sticky="w")
        v = tk.StringVar(value=self.exp.ansi_mode)
        self.evars["ansi_mode"] = v
